INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", "", 4, "vo_empress_100101_001", 1, "vo_empress_100101_001", "ヒヨリ", 0, 100101, "どんなに敵が大勢でも、みんなで\n力を合わせれば絶対大丈夫だよ！\nだから顔を上げてこう！\nごーごー！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", "", 4, "vo_empress_100101_002", 1, "vo_empress_100101_002", "ヒヨリ", 0, 100103, "ううっ、何度も戦う相手もいるけど\nあたし、負けたりなんてしないよ！\n今回だってみんなや騎士くんがいる\nフルパワーでいくよーっ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", "", 4, "vo_empress_100101_003", 2, "vo_empress_100101_003", "ヒヨリ", 0, 100103, "うぅ…すごい力…！\n…でも、なんだか悲しそう\nこの人の気持ちを知りたい\nだからこそ…勝たなきゃ…！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (4, 5, "", "", 4, "vo_empress_100101_004", 3, "vo_empress_100101_004", "ヒヨリ", 100101, 100102, "騎士くんの力があれば、\nあたしは絶対負けないよ！\nみんなが笑顔でいられるように\n一緒にがんばろう！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (5, 5, "", "", 4, "vo_empress_100201_001", 1, "vo_empress_100201_001", "ユイ", 0, 100203, "わたしたちの世界のためにも\nこの世界のためにも、\n絶対に負けられない…！\nがんばろうね、騎士クン", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (6, 5, "", "", 4, "vo_empress_100201_002", 1, "vo_empress_100201_002", "ユイ", 0, 100203, "みんな、怪我したらすぐに教えて！\n…もう誰も失いたくないの\nそのために修行もしたんだから…\n大丈夫、絶対なんとかしてみせる！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (7, 5, "", "", 4, "vo_empress_100201_003", 2, "vo_empress_100201_003", "ユイ", 0, 100203, "世界を『書き換え』するなんて…\nそんな未来、寂しいだけだよ…！\nお願い、これ以上みんなを\n傷つけないで…話を聞いて！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (8, 5, "", "", 4, "vo_empress_100201_004", 3, "vo_empress_100201_004", "ユイ", 100201, 100202, "感じるよ、騎士クンの気持ち…\n抱きしめられてるみたいに\nあったかい…\nぜんぶ終わらせよう！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (9, 5, "", "", 4, "vo_empress_100301_001", 1, "vo_empress_100301_001", "レイ", 0, 100301, "厳しい戦いになるだろうな\n安心してくれ、何があっても\nキミは守る。…いや、違うな\n一緒に、世界を守ろう", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (10, 5, "", "", 4, "vo_empress_100301_002", 1, "vo_empress_100301_002", "レイ", 0, 100303, "手ごわい相手ばかりだな…\nだが引き下がるわけにはいかない\nこちらにだって譲れないものが\nあるんだ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (11, 5, "", "", 4, "vo_empress_100301_003", 2, "vo_empress_100301_003", "レイ", 0, 100303, "くっ…なんて力だ…！\n防ぐだけで精一杯…だが、\n例え剣が折れたとしても、\n私は最後まで戦い続ける！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (12, 5, "", "", 4, "vo_empress_100301_004", 3, "vo_empress_100301_004", "レイ", 100301, 100302, "感じるよ、キミからの愛\nこれがあれば、私はどんな\n敵にだって打ち勝てる！\n見せてやろう、一緒に！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (13, 5, "", "", 4, "vo_empress_100401_001", 1, "vo_empress_100401_001", "ミソギ", 0, 100401, "ミソギとにいちゃんはこれからも\n世界中を冒険して、ワクワクする\nお宝をたくさん見つけるんだ！\nワルモノなんかに邪魔させないよ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (14, 5, "", "", 4, "vo_empress_100401_002", 1, "vo_empress_100401_002", "ミソギ", 0, 100401, "わわ、なんかヤバそうな雰囲気…\nこういう時こそミソギの出番だね！\nとっておきのイタズラ決めて、\nピンチもひっくり返しちゃうよ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (15, 5, "", "", 4, "vo_empress_100401_003", 2, "vo_empress_100401_003", "ミソギ", 0, 100403, "うぅ…あの悪者、すごい迫力だよ…\nもしミソギたちが負けちゃったら、\nミソギもにいちゃんもこの世界も…\n全部おしまい、なんだよね…？", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (16, 5, "", "", 4, "vo_empress_100401_004", 3, "vo_empress_100401_004", "ミソギ", 100401, 100402, "ミソギたちが世界を救っちゃったら\nきっとみんなびっくりするよね！\nどんな顔して驚いてくれるかな…\nにひひ、なんかワクワクしてきた！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (17, 5, "", "", 4, "vo_empress_100501_001", 1, "vo_empress_100501_001", "マツリ", 0, 100501, "歴代オールヒーロー大進撃ッス～！\n自分は新世代のエースってとこッス\nかね？　さあ、ついてくるッス……\nあれ？　みんなどこ？　待って～", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (18, 5, "", "", 4, "vo_empress_100501_002", 1, "vo_empress_100501_002", "マツリ", 0, 100501, "敵は圧倒的な力で、こっちを絶望\nさせる気ッスかね？　だとしたら\n大誤算ッスよ！　むしろ自分の\n正義の魂に火をつけたんスから！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (19, 5, "", "", 4, "vo_empress_100501_003", 2, "vo_empress_100501_003", "マツリ", 0, 100503, "足が……震えるッス……けど！\nこれは武者震いッス……！　だって\nヒーローは絶対に絶対にっ！\n敗北なんてしないんスから……っ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (20, 5, "", "", 4, "vo_empress_100501_004", 3, "vo_empress_100501_004", "マツリ", 100501, 100502, "さあ、手と手をつないで、\n二人で教えてやるッスよ！\nどんな物語でも、悪は必ずヒーロー\nに打ち倒されるってことを！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (21, 5, "", "", 4, "vo_empress_100601_001", 1, "vo_empress_100601_001", "アカリ", 0, 100603, "ひゃぁんっ！\nもう、敵さんが脅かしてくるから\nアカリ、ヘンな声出ちゃいました…\nこういうの、よくないですよっ", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (22, 5, "", "", 4, "vo_empress_100601_002", 1, "vo_empress_100601_002", "アカリ", 0, 100601, "アカリ、お兄ちゃんとシタイコトが\nまだまだいっぱいあるんです！\nだから、私たちの大事な世界も…\n本気で守り抜いてみせますっ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (23, 5, "", "", 4, "vo_empress_100601_003", 2, "vo_empress_100601_003", "アカリ", 0, 100603, "うぅ…こんなに激しく攻められたら\nアカリ、もう壊れちゃいそうです…\nだけどまだまだ…戦えますっ！\nお兄ちゃんが一緒なんですからっ…", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (24, 5, "", "", 4, "vo_empress_100601_004", 3, "vo_empress_100601_004", "アカリ", 100601, 100602, "お兄ちゃんの愛を注いでもらって\nアカリ超絶パワーアップです！\nアカリらしく世界一かわいく、\n世界を救ってみせちゃいますよ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (25, 5, "", "", 4, "vo_empress_100701_001", 1, "vo_empress_100701_001", "ミヤコ", 0, 100701, "アイツらが野放しだと、ミヤコは\n安心してプリンを食べられないの\n今日のプリンと明日のプリンの\nためにも、絶対負けないの！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (26, 5, "", "", 4, "vo_empress_100701_002", 1, "vo_empress_100701_002", "ミヤコ", 0, 100702, "前はミヤコ、悪いヤツに捕まって\n消されそうになって怖かったの…\nでも今度は全然怖くないの！\nオマエが一緒なら平気なの！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (27, 5, "", "", 4, "vo_empress_100701_003", 2, "vo_empress_100701_003", "ミヤコ", 0, 100703, "むうぅ～っ、アイツしつこいの！\nこうなったら、オマエにも\nミヤコのプリン分けてやるの！\nダブルプリンパワーで頑張るの！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (28, 5, "", "", 4, "vo_empress_100701_004", 3, "vo_empress_100701_004", "ミヤコ", 100701, 100702, "アイツはどんなに強くたって、\n独りぼっちのさびしいヤツなの\nでもオマエにはミヤコがいるの！\nミヤコたちなら絶対に勝てるの！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (29, 5, "", "", 4, "vo_empress_100801_001", 1, "vo_empress_100801_001", "ユキ", 0, 100801, "相手が誰であれ、やることは同じ…\nそう…ボクの美しさを見せてあげる\nことさ！　予言しよう…絶世の美の\n前にはどんな敵もひれ伏すと、ね！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (30, 5, "", "", 4, "vo_empress_100801_002", 1, "vo_empress_100801_002", "ユキ", 0, 100801, "少し待っていてくれる？　メイクを\n直さないと。避けられない戦いなら\nせめて美しいボクと戦えることを\n彼らには誇りに思ってほしいからね", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (31, 5, "", "", 4, "vo_empress_100801_003", 2, "vo_empress_100801_003", "ユキ", 0, 100801, "どうせ倒れるなら美しいままで散り\nたいな。ふふ、難しい望みかな…？\nそれでもボクは、最後まで美しく\nあがいてみせるよ、キミと一緒にね", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (32, 5, "", "", 4, "vo_empress_100801_004", 3, "vo_empress_100801_004", "ユキ", 100801, 100802, "ボクがいて、キミがいる。ボクたち\nが勝つのに、これ以上の理由はない\nよね。だって美しい者が勝つ未来の\nほうが、美しいエンディングだもの", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (33, 5, "", "", 4, "vo_empress_100901_001", 1, "vo_empress_100901_001", "アンナ", 0, 100901, "災厄の嵐が吹き荒れ、世界の命運は\n風前の灯が如く儚い。だが絶望には\nまだ早い！　希望はここに在り！\n灯火を掲げよう、盟友シグルドよ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (34, 5, "", "", 4, "vo_empress_100901_002", 1, "vo_empress_100901_002", "アンナ", 0, 100903, "終焉の日、滅びの刻来たれり、か…\nだが、幾度も転生を繰り返しながら\n戦いつづけた我らの宿命を思えば、\nこの程度取るに足らない…はずだ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (35, 5, "", "", 4, "vo_empress_100901_003", 2, "vo_empress_100901_003", "アンナ", 0, 100903, "くっ…なんという禍々しい魔力…！\nもはや世界の滅びも間近…しかし\n疾風の冥姫がここで退くわけには\nいかぬ！　しぶとく抗ってみせるぞ", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (36, 5, "", "", 4, "vo_empress_100901_004", 3, "vo_empress_100901_004", "アンナ", 100901, 100902, "永遠の盟約で結ばれし魂の伴侶…\n世界を滅ぼさんとする災禍の剣も\nこの絆を断ち切ることはできない！\n覚悟するがいい、幻境竜后！！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (37, 5, "", "", 4, "vo_empress_101001_001", 1, "vo_empress_101001_001", "マホ", 0, 101001, "【自警団】のギルドマスターとして\nしゃんとして恥ずかしない姿を\n見せなあきまへんなぁ…王子はん\nしゃなりしゃなり、いきまひょ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (38, 5, "", "", 4, "vo_empress_101001_002", 1, "vo_empress_101001_002", "マホ", 0, 101001, "王子はん、服が破れてますえ？\nこれでよし…うん、完璧や♪\n戦いの中でも、王子はんには\n格好良う居てもらいたいさかいに♪", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (39, 5, "", "", 4, "vo_empress_101001_003", 2, "vo_empress_101001_003", "マホ", 0, 101003, "幻境竜后…大層なお名前してはる\nお后さまが勝負を挑んできはるなら\nうちも、マホマホ王国の姫として…\n正々堂々受けて立ちますえ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (40, 5, "", "", 4, "vo_empress_101001_004", 3, "vo_empress_101001_004", "マホ", 101001, 101002, "強い愛で結ばれた王子と姫を\n引き裂くことは誰にもできまへん\n王子はん…ふたりで一緒に！\nハッピーエンドを迎えまひょ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (41, 5, "", "", 4, "vo_empress_101101_001", 1, "vo_empress_101101_001", "リノ", 0, 101101, "お兄ちゃんがいれば百人力士っ！\n妹パワーも全開でいきますよ～♪\nどんな敵でもドンドンこいですっ！\nあれ？　ちょっと違いました？", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (42, 5, "", "", 4, "vo_empress_101101_002", 1, "vo_empress_101101_002", "リノ", 0, 101101, "これぞまさに『四面そば』…\n敵多すぎでもう大盛りですけど\n秘密結社の一員として、妹として\nこの世界の平和は守り通しますっ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (43, 5, "", "", 4, "vo_empress_101101_003", 2, "vo_empress_101101_003", "リノ", 0, 101103, "あれが幻境竜后…不思議な服…\nじゃなくて、空気がピリピリです…\nちょっとだけ怖いけど…妹として\n絶対に降参なんてしませんよ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (44, 5, "", "", 4, "vo_empress_101101_004", 3, "vo_empress_101101_004", "リノ", 101101, 101102, "私、もう迷いません！\nお兄ちゃんと一緒なら\nどんな敵だって倒しちゃいます！\n妹のポテンシャルは無限大ですよ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (45, 5, "", "", 4, "vo_empress_101201_001", 1, "vo_empress_101201_001", "ハツネ", 0, 101201, "どんなに大変な時でもキミと一緒に\nず～っと乗り越えてきたんだもん！\nだからっ、今回もきっと大丈夫！\n私の魔法できらーん☆　だよっ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (46, 5, "", "", 4, "vo_empress_101201_002", 1, "vo_empress_101201_002", "ハツネ", 0, 101202, "力を使いすぎると眠く…スヤァ…\nはっ、いけないいけない！\nキミ、私が寝ちゃったら起こして！\n…お、王子様のキスとかで…", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (47, 5, "", "", 4, "vo_empress_101201_003", 2, "vo_empress_101201_003", "ハツネ", 0, 101203, "も～！　容赦なさすぎだよぉ！\nそっ、それにさっきまでの戦いの\nせいで、ね、眠気がぁ～っ…\nハ、ハツネちゃん、ピ～ンチ…", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (48, 5, "", "", 4, "vo_empress_101201_004", 3, "vo_empress_101201_004", "ハツネ", 101201, 101202, "幻境竜后さんがどんなに強くても\n今のハツネちゃんは無敵なのだ～！\n大好きなキミと！　シオリンと！\nみんながいる世界を守っちゃうよ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (49, 5, "", "", 4, "vo_empress_101301_001", 1, "vo_empress_101301_001", "ナナカ", 0, 101301, "この世界にはね、たくさんの人の\n『好き』が詰まってるんだよ\nそれをぶち壊すなんて鬼畜の所業\nナナカちゃんが許しはしないぜ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (50, 5, "", "", 4, "vo_empress_101301_002", 1, "vo_empress_101301_002", "ナナカ", 0, 101301, "見るからにヤバい奴らが勢ぞろい！\nでもみんなの世界が狙われてんのに\n日和ってる奴いる？いねえよなぁ！\n全員ぶっ飛ばして世界を救うぞ！！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (51, 5, "", "", 4, "vo_empress_101301_003", 2, "vo_empress_101301_003", "ナナカ", 0, 101303, "あとはラスボスを倒せば勝利ッ！\n第３部完！　…とはいかない感じ？\nていうか逆にピンチな気配？\nどっどうしよう、どうすれば！？", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (52, 5, "", "", 4, "vo_empress_101301_004", 3, "vo_empress_101301_004", "ナナカ", 101301, 101302, "幻境竜后…確かに強敵だったね\nでも今はもう負ける気がしないかな\nだって私は、ただのナナカじゃない\n超ナナカちゃんだから…！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (53, 5, "", "", 4, "vo_empress_101401_001", 1, "vo_empress_101401_001", "カスミ", 0, 101401, "あちらにもなかなかの陰謀家がいる\nようだね。彼女らの最大の誤算は\nここに希代の名探偵がいることさ！\nさあ助手くん。真実を勝ち取ろう！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (54, 5, "", "", 4, "vo_empress_101401_002", 1, "vo_empress_101401_002", "カスミ", 0, 101401, "仕方ない、こうなったら奥の手だ\nミスティ！　セオリー！　…って\nこらぁっ！　変身の最中は待って\nくれるのがお約束だよ！？", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (55, 5, "", "", 4, "vo_empress_101401_003", 2, "vo_empress_101401_003", "カスミ", 0, 101403, "なっ…なんだい、この悪寒は…\n触れてはならない何か…いいや！\n名探偵たるもの巨悪に恐れをなす\nわけにはいかない。絶対に…！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (56, 5, "", "", 4, "vo_empress_101401_004", 3, "vo_empress_101401_004", "カスミ", 101401, 101402, "どんな哀しみでさえ、道理を穢す\n理由にしてはならない。さあ、\nお縄につくんだ。史上最大の迷宮\n事件…終わらせるのは…この私だ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (57, 5, "", "", 4, "vo_empress_101501_001", 1, "vo_empress_101501_001", "ミサト", 0, 101501, "先生は…ううん、先生たちは。\n絶対に負けません。みんなに傷一つ\nつけさせたりはしないわ…！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (58, 5, "", "", 4, "vo_empress_101501_002", 1, "vo_empress_101501_002", "ミサト", 0, 101501, "とっても強大な敵ばかりね…\nでも、大丈夫。焦らず落ち着いて\n戦いましょう。先生がついてるわ\n長引いても、あきらめないで…！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (59, 5, "", "", 4, "vo_empress_101501_003", 2, "vo_empress_101501_003", "ミサト", 0, 101501, "幻境竜后さんの力…すごいわ…\nううん、怖がってる暇なんてないの\n森のみんなを守るためにも…！\n好き勝手したら「めっ」ですからね", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (60, 5, "", "", 4, "vo_empress_101501_004", 3, "vo_empress_101501_004", "ミサト", 101501, 101502, "あなたと一緒なら\n負けたりなんか絶対にしないわ\n最後の一撃まで、\nがんばりましょうね♪", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (61, 5, "", "", 4, "vo_empress_101601_001", 1, "vo_empress_101601_001", "スズナ", 0, 101601, "ツヨそーな敵ばっかりで\nテン下げってカンジだけど\nとりま、うちとヒデサイが\n一緒なら乗り越えられるっしょ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (62, 5, "", "", 4, "vo_empress_101601_002", 1, "vo_empress_101601_002", "スズナ", 0, 101601, "あっ、まってヒデサイ\nマントずれてるから直してあげる\n…よし！　こーゆう時こそ\nおしゃれでテン上げしなきゃね♪", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (63, 5, "", "", 4, "vo_empress_101601_003", 2, "vo_empress_101601_003", "スズナ", 0, 101601, "おにヤバすぎて超わろ～…でもでも\nどうにかやるしかないっしょ～\n勝利のランウェイ遠すぎだけど\nうちら諦めんのはダメだよね～！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (64, 5, "", "", 4, "vo_empress_101601_004", 3, "vo_empress_101601_004", "スズナ", 101601, 101602, "アオハルでバイブス爆上げ♪\n今のうちらは、ムテキだよ～\nハッピーで、もにカワな未来だって\n一緒にゲットするしかないっしょ♪", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (65, 5, "", "", 4, "vo_empress_101701_001", 1, "vo_empress_101701_001", "カオリ", 0, 101701, "歌ったり踊ったり、\nキミと一緒にやりたいことが\nばんないあるからね～！\n絶対に負けられないさ～！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (66, 5, "", "", 4, "vo_empress_101701_002", 1, "vo_empress_101701_002", "カオリ", 0, 101701, "ううっ強そうな敵ばっかりさ～！\n長丁場の戦いにはやっぱりこれよ～\nサーターアンダギー！\n栄養付けて平和を守るさ～♪", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (67, 5, "", "", 4, "vo_empress_101701_003", 2, "vo_empress_101701_003", "カオリ", 0, 101703, "うぅ～、幻境竜后、でーじ強いね～\n私たちも引き下がる気はないよ～！\nどんなに時間がかかっても、絶対に\n諦めたりしないさ～！　だよね～？", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (68, 5, "", "", 4, "vo_empress_101701_004", 3, "vo_empress_101701_004", "カオリ", 101701, 101702, "キミのくれた情熱が、\n私の中で熱く燃え滾ってるよ！\n最高の一撃、キミに見せるさ～！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (69, 5, "", "", 4, "vo_empress_101801_001", 1, "vo_empress_101801_001", "イオ", 0, 101801, "学校生活の邪魔はさせないわ\nだって私、みんなの先生だもの\n明日の授業も世界のことも\n全部守ってみせるんだから！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (70, 5, "", "", 4, "vo_empress_101801_002", 1, "vo_empress_101801_002", "イオ", 0, 101801, "やん！　なんて手ごわい人たちなの\nでも諦めないわ。難しい問題だって\n落ち着いてやればちゃんと解けるの\n戦いも同じよ…いきましょう！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (71, 5, "", "", 4, "vo_empress_101801_003", 2, "vo_empress_101801_003", "イオ", 0, 101803, "これが、幻境竜后さんの力…圧倒\nされちゃいそう。でも、怖がってる\n場合じゃないわ。先生は絶対に、\nここから退かないわ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (72, 5, "", "", 4, "vo_empress_101801_004", 3, "vo_empress_101801_004", "イオ", 101801, 101802, "二人の絆があれば、\n怖いものなんてないわ\n先生と力を合わせて─\nいきましょう♪", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (73, 5, "", "", 4, "vo_empress_102001_001", 1, "vo_empress_102001_001", "ミミ", 0, 102003, "す、すごく強そうな人がいっぱい…\nミミ、怖くてぶるぶるしちゃうけど\nでも泣いちゃったりはしないよっ\nおにいちゃんがいっしょだもん…！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (74, 5, "", "", 4, "vo_empress_102001_002", 1, "vo_empress_102001_002", "ミミ", 0, 102003, "プチグリフォンさんもハナちゃんも\nみゅ～ちゃんも…きっとみんな、\nミミのこと応援してくれてるよね\nだからミミも、がんばるよっ…！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (75, 5, "", "", 4, "vo_empress_102001_003", 2, "vo_empress_102001_003", "ミミ", 0, 102003, "あ、あの竜の人…本気になったら、\nすごく強そうだよ…！このままじゃ\nみんなもミミたちも負けちゃう…？\nやだ、ミミそんなのいやだよっ…", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (76, 5, "", "", 4, "vo_empress_102001_004", 3, "vo_empress_102001_004", "ミミ", 102001, 102002, "おにいちゃんがくれた元気、\n今度はミミたちから届けようね\nもう大丈夫、心配しないでって…\n世界中の、大切なお友だちに…！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (77, 5, "", "", 4, "vo_empress_102101_001", 1, "vo_empress_102101_001", "クルミ", 0, 102101, "怖い人たちがいっぱいですぅ…！\n…でも、みんな頑張ってる…私も\nベルルちゃんみたいに勇気を出して\n…祝福の音を鳴らしましょう！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (78, 5, "", "", 4, "vo_empress_102101_002", 1, "vo_empress_102101_002", "クルミ", 0, 102101, "お兄ちゃん、私、がんばりますぅ\n『ロスト』したお父さんたちの\nためにも…！　怖い時こそ前を見て\n戦ってみせますからっ…！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (79, 5, "", "", 4, "vo_empress_102101_003", 2, "vo_empress_102101_003", "クルミ", 0, 102101, "っ…すごい迫力ですぅ…！\nでも…絶望は必ず乗り越えられる\n胸の中の、希望の音色を信じて…\n逃げたりなんか、しませんよぅ…っ", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (80, 5, "", "", 4, "vo_empress_102101_004", 3, "vo_empress_102101_004", "クルミ", 102101, 102102, "みんなに勇気を与えるために\n主役にも英雄にもなってみせますぅ\nお兄ちゃんがいてくれるなら\n私はなんでもできるんです…！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (81, 5, "", "", 4, "vo_empress_102201_001", 1, "vo_empress_102201_001", "ヨリ", 0, 102201, "こ、これくらいの敵、問題ないわ！\nほんとはちょっと怖いけど…\nゲームの世界を救うことくらい\nこっちは慣れっこなんだから…！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (82, 5, "", "", 4, "vo_empress_102201_002", 1, "vo_empress_102201_002", "ヨリ", 0, 102201, "ここで私たちが負けたら、\n世界が終わっちゃうなんて…\n絶対に認めるわけにはいかないわ！\nアンタも覚悟決めなさいよっ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (83, 5, "", "", 4, "vo_empress_102201_003", 2, "vo_empress_102201_003", "ヨリ", 0, 102203, "ここからが本当の戦いってこと？\nならもう、とことんやってやるわ！\nゲーマーってのは、敵が手強いほど\n燃えてくる生き物なのよ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (84, 5, "", "", 4, "vo_empress_102201_004", 3, "vo_empress_102201_004", "ヨリ", 102201, 102202, "絶対に帰りたい理由ができた…\nそう思うだけで、いくらでも力が\n湧いてくるの。これならもう、\n文句なしの勝ち確よねっ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (85, 5, "", "", 4, "vo_empress_102301_001", 1, "vo_empress_102301_001", "アヤネ", 0, 102301, "私もみんなと一緒に戦うよ！\n悪い人たちはフルスイングで\nあっという間に倒しちゃうから！\n『おうっ！　全員かかってこい！』", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (86, 5, "", "", 4, "vo_empress_102301_002", 1, "vo_empress_102301_002", "アヤネ", 0, 102303, "本当はちょっとだけ怖いけど…\nぷうきちもお兄ちゃんも一緒だもん\n力を合わせて世界を守っちゃうよ\n絶対に負けないんだから！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (87, 5, "", "", 4, "vo_empress_102301_003", 2, "vo_empress_102301_003", "アヤネ", 0, 102303, "ううっあの人、すごく怖いけど\n逃げないよ、戦うって決めたもん\nね、お兄ちゃん、ぷうきち！\n『ここが踏ん張りどころだぞ！』", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (88, 5, "", "", 4, "vo_empress_102301_004", 3, "vo_empress_102301_004", "アヤネ", 102301, 102302, "お兄ちゃんが約束してくれたもん\n今の私ならどんな悪いやつにも\n負けないよ！　宇宙人でもなんでも\n一撃で追い返しちゃうんだから♪", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (89, 5, "", "", 4, "vo_empress_102501_001", 1, "vo_empress_102501_001", "スズメ", 0, 102503, "大変なことになっちゃいましたね…\nで、でも怖がっていられません！\nお嬢さまのことも、あなたのことも\n私が精一杯お支えします！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (90, 5, "", "", 4, "vo_empress_102501_002", 1, "vo_empress_102501_002", "スズメ", 0, 102503, "世界の命運がかかってますから\nドジなんてしてられません！\n…って、ああっ！　言ったそばから\nまた魔法が暴走しちゃいましたっ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (91, 5, "", "", 4, "vo_empress_102501_003", 2, "vo_empress_102501_003", "スズメ", 0, 102503, "す、すごい力です…！\nでもお嬢さまや大切な人をおいて\n逃げるわけにはいきません！\nどこまでもお供します…！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (92, 5, "", "", 4, "vo_empress_102501_004", 3, "vo_empress_102501_004", "スズメ", 102501, 102502, "大切な人と力を合わせれば、\nドジな私でも世界を救えるんです！\n世界規模…いえ、宇宙規模の大掃除\n始めちゃいますよ～っ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (93, 5, "", "", 4, "vo_empress_102601_001", 1, "vo_empress_102601_001", "リン", 0, 102603, "ええー？　こんだけ人数いるならさ\n一人ぐらいいなくても…\n…って空気じゃないわけね\nはいはい、あたしも働きますよー", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (94, 5, "", "", 4, "vo_empress_102601_002", 1, "vo_empress_102601_002", "リン", 0, 102603, "うぅ…あんなのもうバグでしょ！？\nこんな無理ゲーに参戦したんだもん\n終わったらしばらく働かないから！\nダラダラゴロゴロするからね～！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (95, 5, "", "", 4, "vo_empress_102601_003", 2, "vo_empress_102601_003", "リン", 0, 102603, "見てよあのビジュアルさー\nまさにラスボスって感じじゃん…\nでも、どんなゲームでもボスは\n倒せるわけだし…はぁ、やるかー", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (96, 5, "", "", 4, "vo_empress_102601_004", 3, "vo_empress_102601_004", "リン", 102601, 102602, "ここまで来たら後には退けないし\n正真正銘のラスボス戦ってんなら\nあたしも─気合い入れて\n少しぐらいイイとこ見せないとね！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (97, 5, "", "", 4, "vo_empress_102701_001", 1, "vo_empress_102701_001", "エリコ", 0, 102701, "有象無象のクズ虫が、私たちの\n幸せを阻もうとしているようですね\nあぁ、なんて忌々しいのでしょう…\n残らずすり潰しますわ、クスクス…", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (98, 5, "", "", 4, "vo_empress_102701_002", 1, "vo_empress_102701_002", "エリコ", 0, 102701, "クスクス…あら、失礼しましたわ\nこの連中を駆逐すれば、私たちの\n絆はより強く…そんな想像をしたら\n思わず…クスクスクス、クスクス", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (99, 5, "", "", 4, "vo_empress_102701_003", 2, "vo_empress_102701_003", "エリコ", 0, 102703, "あの女…下らない言葉であなた様を\n誑かそうとしたとか。万死に値する\n罪…身の程を思い知らせてやるまで\n決して退きはしませんわ…", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (100, 5, "", "", 4, "vo_empress_102701_004", 3, "vo_empress_102701_004", "エリコ", 102701, 102702, "『壊し屋』と呼ばれる私ですが…\n今はこの力、創るために振るいます\nあなた様との愛、未来…\nクスクス…さあ参りましょう…♪", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (101, 5, "", "", 4, "vo_empress_102801_001", 1, "vo_empress_102801_001", "サレン", 0, 102801, "しっかり頭数揃えてきたわね…\nでもこの程度の力に屈するような\nあたしたちじゃないんだから\nあんたも、サポート頼んだわよ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (102, 3, 10000, 1, 4, "vo_empress_102801_002", 4002, "vo_empress_102801_002", "サレン", 0, 102801, "ちょっと！　なんか向こうに\n教育に悪そうなのがいるんだけど！\nあいつは子どもたちの目に入る前に\nあたしたちで倒すわよ。いい？", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (103, 5, "", "", 4, "vo_empress_102801_003", 2, "vo_empress_102801_003", "サレン", 0, 102803, "もう、強すぎて参っちゃうわね…\nでも諦めるわけにはいかないわ\nこっちだって守らなきゃいけない\nものがたくさんあるんだから！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (104, 5, "", "", 4, "vo_empress_102801_004", 3, "vo_empress_102801_004", "サレン", 102801, 102802, "いつも以上に負ける気がしないわ\nこれもあんたと気持ちが通じた\nおかげね。あんたが側にいる限り、\nあたしはずっと無敵なんだから！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (105, 5, "", "", 4, "vo_empress_102901_001", 1, "vo_empress_102901_001", "ノゾミ", 0, 102903, "この世界が終わっちゃうって…\nアイドル活動も卒業ってコト！？\nファンのみんなが黙ってないよ！\nもちろん私だって…！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (106, 5, "", "", 4, "vo_empress_102901_002", 1, "vo_empress_102901_002", "ノゾミ", 0, 102903, "どんな強い敵にだって屈しない…\n歌って踊って戦うアイドルになる！\nあの日に誓った願い、私の希望！\n今こそ、果たして見せるんだから！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (107, 5, "", "", 4, "vo_empress_102901_003", 2, "vo_empress_102901_003", "ノゾミ", 0, 102903, "幻境竜后…ダンスも歌も、あなたに\nとって価値はないかもしれないけど\n私はこのステージから逃げたり\nなんてしない！　アイドルとして！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (108, 5, "", "", 4, "vo_empress_102901_004", 3, "vo_empress_102901_004", "ノゾミ", 102901, 102901, "星を書き換えるなんてすごい発想…\nプロデューサーとか向いてるかも？\nって、今はそんな場合じゃないか！\n覚悟してよね、幻境竜后！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (109, 5, "", "", 4, "vo_empress_103001_001", 1, "vo_empress_103001_001", "ニノン", 0, 103001, "ショーグンの天下統一を阻む者は\n誰であろうと許しまセン！\nショーグン！　ここはチューシン\nニノンにお任せアーレー！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (110, 5, "", "", 4, "vo_empress_103001_002", 1, "vo_empress_103001_002", "ニノン", 0, 103001, "むむむ…待ち受けているのは強敵\nばかり…それでも退きまセン！\n超烈火之紅蓮旋風で、\nまとめて討ち取ってみせまショウ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (111, 5, "", "", 4, "vo_empress_103001_003", 2, "vo_empress_103001_003", "ニノン", 0, 103003, "な、なんて強さ…このままでは、\nワタシたちは負けてしまいます…\n…いいえ。いいえ！　ショーグンの\nためにも、諦めることなど…っ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (112, 5, "", "", 4, "vo_empress_103001_004", 3, "vo_empress_103001_004", "ニノン", 103001, 103002, "感じマス、ショーグンの愛を…！\n今ならどんな敵が来ても、\nカッサイ、ボンサイ、\nオチャノコサイサイデース！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (113, 5, "", "", 4, "vo_empress_103101_001", 1, "vo_empress_103101_001", "シノブ", 0, 103101, "この世界が、明日を迎えることなく\n滅んでしまうかもしれない…\n運命の岐路が、目の前にあります\n抗えるのは、私たちだけです…！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (114, 5, "", "", 4, "vo_empress_103101_002", 1, "vo_empress_103101_002", "シノブ", 0, 103101, "何よりも色濃い死の気配が、\n世界に満ちていくのを感じます\nでも、倒れるわけにはいきません\n最後まで戦いましょう、全力で", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (115, 5, "", "", 4, "vo_empress_103101_003", 2, "vo_empress_103101_003", "シノブ", 0, 103103, "これほどまでに強大な力なんて…\n占いも、未来は滅びの闇に覆われ\nつつある、と出ています…それでも\n希望を手放すわけには…！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (116, 5, "", "", 4, "vo_empress_103101_004", 3, "vo_empress_103101_004", "シノブ", 103101, 103101, "命ある者にとって、死の運命は\n決して避けられないもの…\nでも、今この時ではないはずです\n戦いましょう、未来のために…！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (117, 5, "", "", 4, "vo_empress_103201_001", 1, "vo_empress_103201_001", "アキノ", 0, 103201, "これ以上の狼藉は許しません！\nウィスタリア家の名に懸けて、\nこの世界の人々を守ります…必ずや\n貴人としての役目を果たしますわ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (118, 5, "", "", 4, "vo_empress_103201_002", 1, "vo_empress_103201_002", "アキノ", 0, 103201, "互いを利するウィンウィンの関係\nそれが商売の鉄則です。力を振るい\n一方的に望みを押し付けるなんて、\n倒産まっしぐらですわよっ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (119, 5, "", "", 4, "vo_empress_103201_003", 2, "vo_empress_103201_003", "アキノ", 0, 103203, "幻境竜后…すさまじい力ですわね\n世界を意のままにするという野望も\n決して絵空事ではないのでしょう…\nそれでも私は…諦めませんわよ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (120, 5, "", "", 4, "vo_empress_103201_004", 3, "vo_empress_103201_004", "アキノ", 103201, 103202, "人々を守ることが力ある者の務め…\nそしてあなたさまと共に生きること\nそれが私の務めであり願いですわ！\nこの想いは、止まりませんわよ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (121, 5, "", "", 4, "vo_empress_103301_001", 1, "vo_empress_103301_001", "マヒル", 0, 103301, "こんな舞台で漫才したって\nみんなもお天道さんもどんよりだべ\n安心して笑ってられる世界を\nオラたちで取り戻すど！　おー！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (122, 5, "", "", 4, "vo_empress_103301_002", 1, "vo_empress_103301_002", "マヒル", 0, 103301, "お、おっかねぇ連中だ…！\nでも…スベっちまう怖さに比べりゃ\nマシだべな！　あははっ！\nみんなの笑顔は、オラが守るべ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (123, 5, "", "", 4, "vo_empress_103301_003", 2, "vo_empress_103301_003", "マヒル", 0, 103303, "あの子、芸人として光りそうだべな\n幻境竜后なんて仰々しい名前も…\nノーヴィジョンズノープロブレム！\n…あたた！　激しいツッコミだべ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (124, 5, "", "", 4, "vo_empress_103301_004", 3, "vo_empress_103301_004", "マヒル", 103301, 103302, "逆境も笑顔で切り開く…\nあんちゃんと一緒なら\nできる気がすんだ\nオラたちの芸人魂、見せてやるべ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (125, 5, "", "", 4, "vo_empress_103401_001", 1, "vo_empress_103401_001", "ユカリ", 0, 103401, "元…ううん、正しき聖騎士として\nここでやらなきゃいつやるのよ…！\n必ずみんなを守りきってみせるわ\n怪我をした人は私のところへ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (126, 5, "", "", 4, "vo_empress_103401_002", 1, "vo_empress_103401_002", "ユカリ", 0, 103401, "…んぐっ…ごくっ…ぷは～っ♪\nよぉし気合十分らわ～っ！\nこら～幻境竜后～っ！　隠れて\nないでかかってきなさ～い！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (127, 5, "", "", 4, "vo_empress_103401_003", 2, "vo_empress_103401_003", "ユカリ", 0, 103403, "ひっく…ふぇ？　な、なに……？\nと、とっても大きいのが見えりゅ…\n…なっ、なによこれえぇぇ！\nこ、これが幻境竜后の姿なのぉ～っ", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (128, 5, "", "", 4, "vo_empress_103401_004", 3, "vo_empress_103401_004", "ユカリ", 103401, 103402, "私は無敵らのよ～♪　この世界と\nキミと築く\n素敵な未来のために…幻境竜后！\nぶっとばしてやるわぁ～っ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (129, 5, "", "", 4, "vo_empress_103601_001", 1, "vo_empress_103601_001", "キョウカ", 0, 103603, "ここで私たちが諦めたら、このまま\n世界が終わっちゃう！　そんなの\n絶対ダメです！　負けられません！\n私たちで全部退治しちゃいますよ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (130, 5, "", "", 4, "vo_empress_103601_002", 1, "vo_empress_103601_002", "キョウカ", 0, 103603, "うぅ、ふしんしゃがいっぱいです！\n…でも、このくらいへっちゃらです\nお母さんが心配する前に、早く\n片付けておうちに帰りましょう！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (131, 5, "", "", 4, "vo_empress_103601_003", 2, "vo_empress_103601_003", "キョウカ", 0, 103601, "あれが私たちの敵、幻境竜后…\nほ、本当に勝てるんでしょうか…？\n立ってるだけで体が震えて…でも、\n弱気になっちゃダメですよねっ…！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (132, 5, "", "", 4, "vo_empress_103601_004", 3, "vo_empress_103601_004", "キョウカ", 103601, 103602, "正直に言うと…まだ少し怖いです\n我慢したって怖くて体が震えます\nでも、あなたがいてくれるから…\n勇気だって同じくらい湧いてきます", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (133, 5, "", "", 4, "vo_empress_103701_001", 1, "vo_empress_103701_001", "トモ", 0, 103701, "滅ぼすための力に、守るための力が\n屈するわけにはいかないよ。\nこの剣の誇りに賭けて、必ず止める\nさあ、来い！　ミクマ流が相手だ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (134, 5, "", "", 4, "vo_empress_103701_002", 1, "vo_empress_103701_002", "トモ", 0, 103701, "追いかけっこでもしようか\n鬼さんこちら♪　…って、まだ\n来るの！？　不意打ちされる側に\nなるのは趣味じゃないんだけどな！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (135, 5, "", "", 4, "vo_empress_103701_003", 2, "vo_empress_103701_003", "トモ", 0, 103701, "踏み込めない…踏み込む隙がない…\n向きあってるだけで精一杯なんて…\nで、でも…こんなところで\n剣を捨てるわけにはっ…！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (136, 5, "", "", 4, "vo_empress_103701_004", 3, "vo_empress_103701_004", "トモ", 103701, 103702, "勝機は私の中にあったんだ…！\nあなたとの、\n一番強くて絶対に消えない絆\nそれが、あいつを倒す力をくれる！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (137, 5, "", "", 4, "vo_empress_103801_001", 1, "vo_empress_103801_001", "シオリ", 0, 103801, "手ごわい相手ですね…\nでも、不思議と怖くありません\nあなたと力を合わせれば\n何とかなるって信じていますから", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (138, 5, "", "", 4, "vo_empress_103801_002", 1, "vo_empress_103801_002", "シオリ", 0, 103801, "あなたの応援で、私の胸に\n愛と希望が満ち溢れています…\n今こそ魔法狩人ピュアリー★シオリ\nに大変身する時なのかも…？", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (139, 5, "", "", 4, "vo_empress_103801_003", 2, "vo_empress_103801_003", "シオリ", 0, 103803, "とてつもない力ですね…\nでも、諦めたくありません\n何度だって立ち上がってみせます\n今までと同じように…！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (140, 5, "", "", 4, "vo_empress_103801_004", 3, "vo_empress_103801_004", "シオリ", 103801, 103802, "今の私に怖いものなんてありません\nあなたとの愛の力がありますから♪\n…少し舞い上がり過ぎですかね？\nふふ、気を引き締めてがんばります", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (141, 5, "", "", 4, "vo_empress_104001_001", 1, "vo_empress_104001_001", "アオイ", 0, 104001, "進んで目立ちたくはないですけど…\nと、ともっ…友達を守るためなら！\nＢＢ団として、勇気を振り絞って…\n団長さんと一緒に戦います！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (142, 5, "", "", 4, "vo_empress_104001_002", 1, "vo_empress_104001_002", "アオイ", 0, 104002, "いいい、一緒に戦う仲間がこんなに\nいてくれるなんて、こ、心強いの\n助太郎～っ！　私も末席で参加し…\nじゃなくてっ！　全力で戦います！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (143, 5, "", "", 4, "vo_empress_104001_003", 2, "vo_empress_104001_003", "アオイ", 0, 104003, "ううっ、手も足も声も震えてます…\nで、でも逃げも隠れもしませんよっ\n逃げたらぼっちが廃ります！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (144, 5, "", "", 4, "vo_empress_104001_004", 3, "vo_empress_104001_004", "アオイ", 104001, 104002, "私はひとりぼっちじゃない…\n団長さんと繋がった絆があるから\nどんな敵だって怖くないですっ！\n行きましょう、団長さんっ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (145, 5, "", "", 4, "vo_empress_104201_001", 1, "vo_empress_104201_001", "チカ", 0, 104203, "やめてくれる気はなさそうです\nそれなら私も、絶対にここを\n動きはしません…！　だって\n私は……ワガママですからっ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (146, 5, "", "", 4, "vo_empress_104201_002", 1, "vo_empress_104201_002", "チカ", 0, 104201, "私の唱喚術は人を守るためのもの…\nこの世界の森羅万象を護るための\nもの。今こそ、声の限り歌います\nこの子たちと、あなたと共に！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (147, 5, "", "", 4, "vo_empress_104201_003", 2, "vo_empress_104201_003", "チカ", 0, 104203, "精霊たちが震えてる…今までの\n敵とは訳が違うってことですよね…\n私もここに立っているのが精一杯…\n怖いけど…でも！　退きません…！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (148, 5, "", "", 4, "vo_empress_104201_004", 3, "vo_empress_104201_004", "チカ", 104201, 104201, "今なら歌える気がします。ずっと\n探していた、誰かの心を震わせる歌\n幻境竜后…孤独なあなたの心にも\n私たちの歌が届くように…！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (149, 5, "", "", 4, "vo_empress_104301_001", 1, "vo_empress_104301_001", "マコト", 0, 104301, "敵さんがどんだけ強くったって\n後には退けねぇんだ！　そうだろ、\nさぁ、覚悟しやがれよ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (150, 5, "", "", 4, "vo_empress_104301_002", 1, "vo_empress_104301_002", "マコト", 0, 104301, "くっ、敵の連中、ずいぶんな戦力\n揃えてきやがった。けど、\n数でも気合でも負けやしねぇ！\nあたしが嚙み砕いてやる！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (151, 5, "", "", 4, "vo_empress_104301_003", 2, "vo_empress_104301_003", "マコト", 0, 104303, "幻境竜后とやら…マジで\n洒落になんねえな。だからって\n引き下がるわけにゃいかねえ！\n持ちこたえてやるぜ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (152, 5, "", "", 4, "vo_empress_104301_004", 3, "vo_empress_104301_004", "マコト", 104301, 104302, "どんな強い敵でも\n恐れる必要なんてないよな\nさあ、いっしょに─最大パワーで\nブチのめしてやろうぜっ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (153, 5, "", "", 4, "vo_empress_104401_001", 1, "vo_empress_104401_001", "イリヤ", 0, 104401, "ここはいずれわらわが支配する世界\nつまり、わが領地に等しきもの…\n奴らのような不届き者の蛮行、\n見過ごすわけにはいかぬわ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (154, 5, "", "", 4, "vo_empress_104401_002", 1, "vo_empress_104401_002", "イリヤ", 0, 104401, "厳しい戦いになりそうじゃな…\nお主もわらわから離れるでないぞ\nも、もちろん、大人の姿を保つのに\n都合がいいからというだけじゃ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (155, 5, "", "", 4, "vo_empress_104401_003", 2, "vo_empress_104401_003", "イリヤ", 0, 104401, "何とも恐ろしく禍々しい力じゃ…\nだが、我が意志は決して挫けぬ\n高貴なる吸血鬼の誇りに懸けて、\n最後まで戦い抜いてみせようぞ", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (156, 5, "", "", 4, "vo_empress_104401_004", 3, "vo_empress_104401_004", "イリヤ", 104401, 104401, "己が誰を敵に回したのかを、\n骨の髄まで知らしめてやろうぞ\nここにいるのは固き絆で結ばれし\n伝説の吸血鬼とその眷属じゃ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (157, 5, "", "", 4, "vo_empress_104501_001", 1, "vo_empress_104501_001", "クウカ", 0, 104501, "とっても強そうな敵ですっ…\n当然、攻撃も強烈になるはず…\nドＳさん、ここはどうかクウカに、\n先頭をお任せください！　ぐふふ♪", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (158, 5, "", "", 4, "vo_empress_104501_002", 1, "vo_empress_104501_002", "クウカ", 0, 104501, "安心してドＳさんに虐げてもらう\nためにもクウカは負けられませんっ\nこの世界で一番のドＭとして、\n全力で責められに行ってきますっ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (159, 5, "", "", 4, "vo_empress_104501_003", 2, "vo_empress_104501_003", "クウカ", 0, 104503, "ううっ、刺激が強すぎますよ…っ\nだけど、ドＭのプライドにかけて\nここで退くわけにはいきませんっ！\nドＳさんのこと、守り抜きます…っ", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (160, 5, "", "", 4, "vo_empress_104501_004", 3, "vo_empress_104501_004", "クウカ", 104501, 104502, "その視線は、『全部終わったらたっ\nぷり調教してやるからな』という\n意味ですね！　ぐふふっ…♪　負け\nられない理由がまた一つできました", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (161, 5, "", "", 4, "vo_empress_104601_001", 1, "vo_empress_104601_001", "タマキ", 0, 104601, "強そうなやつらが目白押しにゃ～\n短期戦でどうにかならないなら…\n長丁場に向けて、特別価格の\nたい焼きはいかがかにゃ～？", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (162, 5, "", "", 4, "vo_empress_104601_002", 1, "vo_empress_104601_002", "タマキ", 0, 104601, "ファントムキャッツは\n狙った獲物を逃がさないにゃ！\nあたしたちの未来を手に入れるまで\nとことんやってやるにゃ～！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (163, 5, "", "", 4, "vo_empress_104601_003", 2, "vo_empress_104601_003", "タマキ", 0, 104603, "にゃにゃっ、これが幻境竜后…\nとんでもない力だにゃ\nでも、ここで逃げたらファントム\nキャッツの名が廃るにゃ～！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (164, 5, "", "", 4, "vo_empress_104601_004", 3, "vo_empress_104601_004", "タマキ", 104601, 104602, "ファントムキャッツにかかれば\nどんなに強い悪党でも\n滅びる運命にゃ！\nとっておきの一撃、キメるにゃ～！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (165, 5, "", "", 4, "vo_empress_104701_001", 1, "vo_empress_104701_001", "ジュン", 0, 104701, "全軍展開！　敵の一体たりとも\nこの先へは進ませるな\n苦しいときは、私の背中を見るんだ\n我々は決して折れはしない！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (166, 5, "", "", 4, "vo_empress_104701_002", 1, "vo_empress_104701_002", "ジュン", 0, 104701, "少年…\n最前線は危険だが、下がるつもりは\nないのか？　ふふ、やはり強情だな\nならば、私の隣を絶対に離れるな", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (167, 5, "", "", 4, "vo_empress_104701_003", 2, "vo_empress_104701_003", "ジュン", 0, 104701, "な…なんだ…この冷たい闘気は…！\nみんな、いったん退がれ！\n安心しろ、ここは私が防ぎきる\n…たとえ…この身に代えても", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (168, 5, "", "", 4, "vo_empress_104701_004", 3, "vo_empress_104701_004", "ジュン", 104701, 104701, "幻境竜后、貴様は絶対に勝てないよ\n自分の身以上に、大切な誰かを\n守りたいという、人間の持つ尊い\n想いを、知ることのない貴様は…！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (169, 5, "", "", 4, "vo_empress_104801_001", 1, "vo_empress_104801_001", "ミフユ", 0, 104801, "バイト仲間とこの世界のみんなを\n守るために！　私たちのやるべき\nことはただ一つ！　いいわね？\n─最高の効率で倒すわよ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (170, 5, "", "", 4, "vo_empress_104801_002", 1, "vo_empress_104801_002", "ミフユ", 0, 104801, "相手も数が多いし、短期決戦とは\nいかないわね…って！　早く\n勝たなきゃバイトに遅刻しちゃう\nもっと効率アップしていくわよ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (171, 5, "", "", 4, "vo_empress_104801_003", 2, "vo_empress_104801_003", "ミフユ", 0, 104803, "幻境竜后……本当に圧倒的な力ね\nだからってそう簡単に諦められる\nわけはないわよね。たとえそれが\n非効率的な判断だとしても……！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (172, 5, "", "", 4, "vo_empress_104801_004", 3, "vo_empress_104801_004", "ミフユ", 104801, 104802, "こんなに迂遠で非効率的な計画を\n立てる敵になんて負けないわ！\n効率を極めた私たちの一撃を\n叩きつけてやりましょう！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (173, 5, "", "", 4, "vo_empress_104901_001", 1, "vo_empress_104901_001", "シズル", 0, 104902, "安心していいよ、弟くん♪\n弟くんには指一本触れさせない！\n絶対に弟くんを守るから…だって\nそれがお姉ちゃんの役目だもんね！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (174, 5, "", "", 4, "vo_empress_104901_002", 1, "vo_empress_104901_002", "シズル", 0, 104902, "準備はできてる、弟くん？\n不安なら手をつないであげよっか？\n大丈夫、お姉ちゃんと弟くんなら\n悪いやつらを全部倒せるはず♪", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (175, 5, "", "", 4, "vo_empress_104901_003", 2, "vo_empress_104901_003", "シズル", 0, 104903, "幻境竜后…手強そうだね…\nでも諦めないよ、絶対に！\n弟くんとお姉ちゃんの大切な世界\nきっと守り抜いてみせるんだから！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (176, 5, "", "", 4, "vo_empress_104901_004", 3, "vo_empress_104901_004", "シズル", 104901, 104902, "お姉ちゃんと弟くんの力を合わせて\n二人の未来を、みんなの未来を\n一緒に守ろっ！　あ、終わったら\nたくさん甘えさせてあげるからね♪", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (177, 5, "", "", 4, "vo_empress_105001_001", 1, "vo_empress_105001_001", "ミサキ", 0, 105001, "アブナイキレイなお姉さんはね\n『ふれーばー』だから許されるの！\nこんなメチャクチャにするなんて…\n本物の大人のレディが勝負よ勝負！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (178, 5, "", "", 4, "vo_empress_105001_002", 1, "vo_empress_105001_002", "ミサキ", 0, 105001, "アタシは全世界代表の\n大人のレディなんだから！\nアンタ！\nしっかりエスコートしてよね！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (179, 5, "", "", 4, "vo_empress_105001_003", 2, "vo_empress_105001_003", "ミサキ", 0, 105003, "コ、コイツが幻境竜后…っ\n…正直怖いけど…絶対に逃げないわ\n大人のレディのプライドにかけて\n戦い抜いてやるんだから…！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (180, 5, "", "", 4, "vo_empress_105001_004", 3, "vo_empress_105001_004", "ミサキ", 105001, 105002, "終わったらデートよ！　だって…\n約束があった方がやる気出るもん♪\nよーし！　大人のレディとして\n最後はエレガントに決めるわよ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (181, 5, "", "", 4, "vo_empress_105101_001", 1, "vo_empress_105101_001", "ミツキ", 0, 105101, "なんて重圧かしら…でも、あいにく\n私も伊達に修羅場をくぐってないの\nさあ、かかってきなさい！\n裏の人生経験、見せてあげるわ…♪", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (182, 5, "", "", 4, "vo_empress_105101_002", 1, "vo_empress_105101_002", "ミツキ", 0, 105101, "私は闇医者である前に科学者なの\nあなたたち、実験に協力してくれる\nわよね？　隻眼の悪魔の名は\n伊達じゃないのよ？　覚悟しなさい", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (183, 5, "", "", 4, "vo_empress_105101_003", 2, "vo_empress_105101_003", "ミツキ", 0, 105101, "到底不可能に思える挑戦こそ\n科学者の腕の見せどころなのよ\n青い薔薇のごとく、人の信念が\n起こす奇跡を見せてあげるわ…！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (184, 5, "", "", 4, "vo_empress_105101_004", 3, "vo_empress_105101_004", "ミツキ", 105101, 105101, "迷いのない言葉をもらったんだもの\n私だってもう、覚悟を決めたわ\nこの先の未来を君と生きていく…\nそのために全力をぶつけるだけよ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (185, 5, "", "", 4, "vo_empress_105201_001", 1, "vo_empress_105201_001", "リマ", 0, 105201, "私のお友達をいじめるなら\n相手になるわ！\nたとえ魔物に間違えられても\n絶対にここを引かないから！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (186, 3, 10000, 1, 4, "vo_empress_105201_002", 4002, "vo_empress_105201_002", "リマ", 0, 105201, "ね、ねぇ…\nちょっと聞きたいんだけど\n毛皮もないのにあの姿なのよね？\n風邪引いたりしないのかしら？", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (187, 5, "", "", 4, "vo_empress_105201_003", 2, "vo_empress_105201_003", "リマ", 0, 105201, "ひづめは割れちゃいそうだし…\n毛並みだってボロボロだし…\nでも後ろには彼がいるんだもの\n恋する乙女の負けられない戦いよ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (188, 5, "", "", 4, "vo_empress_105201_004", 3, "vo_empress_105201_004", "リマ", 105201, 105202, "私はもう恋する女の子じゃないわ…\n王子様の愛を受け取ったお姫様よ！\n彼が私を守ってくれるように\n私が彼を守ってみせるわ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (189, 5, "", "", 4, "vo_empress_105301_001", 1, "vo_empress_105301_001", "モニカ", 0, 105303, "どれほど強大な敵であろうと、\n我々【ヴァイスフリューゲル\nランドソル支部】がいれば安心…\nこら！　皆纏まって行動しろー！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (190, 5, "", "", 4, "vo_empress_105301_002", 1, "vo_empress_105301_002", "モニカ", 0, 105301, "敵戦力は強大無比…だが、\n私たちなら必ず倒せるはずだ！\n白き翼の名のもとに、今こそ\n正義の鉄槌を下してやる！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (191, 5, "", "", 4, "vo_empress_105301_003", 2, "vo_empress_105301_003", "モニカ", 0, 105301, "これが幻境竜后の底力か…\n名にし負う圧倒的な強さだな…\nだが！　長期戦になろうとも必ずや\n私たちが勝利の旗を掲げるのだ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (192, 5, "", "", 4, "vo_empress_105301_004", 3, "vo_empress_105301_004", "モニカ", 105301, 105302, "貴公と一緒ならば\nなんだってできるとも\nさあ、最後の一撃を加えてやろう！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (193, 5, "", "", 4, "vo_empress_105401_001", 1, "vo_empress_105401_001", "ツムギ", 0, 105401, "強そうな相手ばかりですけど\nだからなんだっていうんですか！\nほら、騎士さんも気合い入れて！\n一緒に戦いますよ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (194, 3, 10000, 1, 4, "vo_empress_105401_002", 4002, "vo_empress_105401_002", "ツムギ", 0, 105403, "なんか敵に下着姿…っていうか\nほぼ裸みたいな人いません？\n…え？　あれ趣味なんですか？\nあの人の？　…正気ですか？", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (195, 5, "", "", 4, "vo_empress_105401_003", 2, "vo_empress_105401_003", "ツムギ", 0, 105403, "世界を作り変えようなんて\n幻境竜后、絶対許せません…！\nあとその服！　そんなに破いて！\nデザイナーが泣いてますよ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (196, 5, "", "", 4, "vo_empress_105401_004", 3, "vo_empress_105401_004", "ツムギ", 105401, 105401, "私と騎士さんの糸は\n絶対に切れません！\nだから…今ここで\nすべてを終わらせましょう！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (197, 5, "", "", 4, "vo_empress_105501_001", 1, "vo_empress_105501_001", "アユミ", 0, 105503, "つ、強そうな人たちばっかり…\n逃げたいくらいだけど、\nそれはダメ。先輩をケガさせない\nためにも、私も頑張らなくちゃ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (198, 5, "", "", 4, "vo_empress_105501_002", 1, "vo_empress_105501_002", "アユミ", 0, 105501, "私なんかが大それたことを言うのは\n笑われるかも…でも…！\n先輩を守るために、\n世界を守ってみせます…！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (199, 5, "", "", 4, "vo_empress_105501_003", 2, "vo_empress_105501_003", "アユミ", 0, 105503, "な、なんて大きさ、存在感…！\nまるで私とは真逆の人…\nこうして立ってるだけで、\n私、消えちゃいそうです～っ…！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (200, 5, "", "", 4, "vo_empress_105501_004", 3, "vo_empress_105501_004", "アユミ", 105501, 105502, "先輩がそばにいてくれる…\nそれだけで勇気が湧いてきて\n前へ進む力がもらえるんです\n行きましょう、先輩！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (201, 5, "", "", 4, "vo_empress_105601_001", 1, "vo_empress_105601_001", "ルカ", 0, 105601, "雁首並べてよくもまあ…\nこりゃ長丁場になりそうだ\n釣りと同じくじっくり腰を据えて\n勝負しようじゃないか", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (202, 5, "", "", 4, "vo_empress_105601_002", 1, "vo_empress_105601_002", "ルカ", 0, 105601, "世界の危機とあっちゃあ\nアタシたち黄昏時の住人でも\n黙っちゃいられないね！\nひとっ働きさせてもらおうかい！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (203, 5, "", "", 4, "vo_empress_105601_003", 2, "vo_empress_105601_003", "ルカ", 0, 105603, "へぇ、これが幻境竜后かい…\nたいそうな強さだけど、アタシも\nここで退くわけにはいかないんだ\n心に差した刃に懸けて、いくよ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (204, 5, "", "", 4, "vo_empress_105601_004", 3, "vo_empress_105601_004", "ルカ", 105601, 105602, "刀も恋も揃ったアタシは天下無双！\nお前さんが側にいてくれれば、\nどんな巨悪にだって勝てるよ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (205, 5, "", "", 4, "vo_empress_105801_001", 1, "vo_empress_105801_001", "ペコリーヌ", 0, 105803, "また一緒に、みんなで\nおいしいごはんを食べるために！\nわたしたちは、絶対に負けません！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (206, 3, 10000, 1, 4, "vo_empress_105801_002", 4003, "vo_empress_105801_002", "ペコリーヌ", 0, 105801, "フレイヤさんだけじゃなく、\n覇瞳皇帝やミロクまで！\n長丁場になりそうです…\n栄養補給はしっかりしましょうね！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (207, 5, "", "", 4, "vo_empress_105801_003", 2, "vo_empress_105801_003", "ペコリーヌ", 0, 105803, "これが、幻境竜后の力…\nやばいですね。正直、どうやって\n止めればいいのか分かりません\nでもここで引き下がるわけには…っ", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (208, 5, "", "", 4, "vo_empress_105801_004", 3, "vo_empress_105801_004", "ペコリーヌ", 105801, 105802, "あなたの愛情でお腹いっぱいの\n無敵ペコリーヌ参上です☆\nわたしたちの明日を、この世界を\n全力全開で取り戻しましょう！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (209, 5, "", "", 4, "vo_empress_105901_001", 1, "vo_empress_105901_001", "コッコロ", 0, 105903, "みなさまとのおいしいごはんのため\n負けるわけにはまいりません\n主さま、お背中はお任せください\nわたくしがお守りいたします！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (210, 5, "", "", 4, "vo_empress_105901_002", 1, "vo_empress_105901_002", "コッコロ", 0, 105905, "敵は強大…ですが、心強い仲間の\nみなさまが一緒でございます\n…全員主さまとお知り合いなのは\n未だに信じられませんが…", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (211, 5, "", "", 4, "vo_empress_105901_003", 2, "vo_empress_105901_003", "コッコロ", 0, 105903, "まだこのような力が…！？\n主さま、ここはお下がりください\nたとえこの身に何があろうと、\nあなただけはお守りいたします…！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (212, 5, "", "", 4, "vo_empress_105901_004", 3, "vo_empress_105901_004", "コッコロ", 105901, 105902, "主さまとの絆がある限り\nわたくしは絶対に負けません！\nいついかなるときも、何があろうと\nわたくしが導いてみせます！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (213, 3, 10000, 1, 4, "vo_empress_106001_001", 4005, "vo_empress_106001_001", "キャル", 0, 106001, "また陛下と戦うのね…大丈夫、一番\n大事なものが何なのかは分かってる\n…だから、あたしも負けないわ\n─陛下、よろしくお願いします！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (214, 5, "", "", 4, "vo_empress_106001_002", 1, "vo_empress_106001_002", "キャル", 0, 106003, "この世界を好き勝手しようだなんて\nそういう連中に人生振り回されるの\nこちとらもううんざりなのよ！\n全員ぶっ飛ばしてやるんだから！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (215, 5, "", "", 4, "vo_empress_106001_003", 2, "vo_empress_106001_003", "キャル", 0, 106003, "なんなのよあの力、反則でしょ…\nだけどさ、どんなに怖くたって\nあたしはここから退かないわ\n他に行くとこも、ないんだからっ…", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (216, 5, "", "", 4, "vo_empress_106001_004", 3, "vo_empress_106001_004", "キャル", 106001, 106002, "絆の力でパワーアップ、なんて\nガラじゃないと思ってたけど…\n今だけは調子に乗らせてもらうわ\nもう負ける気がしないってねっ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (217, 5, "", "", 4, "vo_empress_106101_001", 1, "vo_empress_106101_001", "ノウェム", 0, 106102, "晶に直してもらって\n天楼覇断剣も新品同然だ！\n気合い入れていくぞオクトー！\nはーっはっはっはー！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (218, 5, "", "", 4, "vo_empress_106101_002", 1, "vo_empress_106101_002", "ノウェム", 0, 106101, "真那、覚悟しとけよ！\nオマエが積み上げてきた悪事…\nこの大悪党がまとめて\nぶっ壊してやるからな！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (219, 5, "", "", 4, "vo_empress_106101_003", 2, "vo_empress_106101_003", "ノウェム", 0, 106103, "今までの借り…ここでまとめて\n返してやるって、決めてたんだ\nオマエだけは絶対に、許さない\n…オマエが、どれだけ強くても…っ", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (220, 5, "", "", 4, "vo_empress_106101_004", 3, "vo_empress_106101_004", "ノウェム", 106101, 106102, "大悪党のプリンセス？\nなんだかよくわからないけど──\nとにかく、あの化け物ぶった斬りに\n行くぞ！　ついてこい！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (221, 5, "", "", 4, "vo_empress_106401_001", 1, "vo_empress_106401_001", "シェフィ", 0, 106401, "絶対に負けられない戦いね\nおいしいごはんと、本当の\nハッピーエンドのために\n気を引き締めていきましょう", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (222, 3, 10000, 1, 4, "vo_empress_106401_002", 4004, "vo_empress_106401_002", "シェフィ", 0, 106403, "ミロク…まだ生きていたのね…！\nあの男は私が相手するわ\n兄さんの分もまとめて、\n今ここで借りを返さないと！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (223, 5, "", "", 4, "vo_empress_106401_003", 2, "vo_empress_106401_003", "シェフィ", 0, 106401, "こんな力を隠してたなんて…！\n…まだよ。まだ諦めないわ\nどんな方法を使ってでも\nみんなだけは助けてみせる…！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (224, 5, "", "", 4, "vo_empress_106401_004", 3, "vo_empress_106401_004", "シェフィ", 106401, 106402, "不思議ね…あなたとの思い出で\n全身に力が満ちていくような気持ち\n…私たちが紡いできた絆を\n幻境竜后に見せてやりましょう", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (225, 5, "", "", 4, "vo_empress_106501_001", 1, "vo_empress_106501_001", "カヤ", 0, 106501, "おまえら、ケンカ売りたいんだろ？\nこの世界そのものに！\nならこっち向けよ。喧嘩屋のオレが\nまとめて買ってやるぜ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (226, 5, "", "", 4, "vo_empress_106501_002", 1, "vo_empress_106501_002", "カヤ", 0, 106501, "オレがドラゴン族なのも、\nこんな力を持ってるのも…きっと\n今日、この時のためだったんだ\nそうだろ？", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (227, 5, "", "", 4, "vo_empress_106501_003", 2, "vo_empress_106501_003", "カヤ", 0, 106503, "ウソだろ…オレが竦んじまってる…\nアイツのあの赤い眼から、眼を\nそらすんじゃねぇ…！　ドラゴン族\nのケンカ最強は…オレ様だろッ…！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (228, 5, "", "", 4, "vo_empress_106501_004", 3, "vo_empress_106501_004", "カヤ", 106501, 106501, "自分の力に、ずっとビビッてた\nでも今は何よりこの力を頼もしく\n感じるぜ。テメェをぶっ倒し…\n明日を迎えるための力がなァ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (229, 5, "", "", 4, "vo_empress_106601_001", 1, "vo_empress_106601_001", "イノリ", 0, 106603, "どきやがれです！　最強ギャングが\nおまえのシマ分捕りにきたですよ！\nこんだけ仲間がいりゃ楽勝ですね♪\n尻尾巻いて逃げ出しやがれです！！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (230, 5, "", "", 4, "vo_empress_106601_002", 1, "vo_empress_106601_002", "イノリ", 0, 106601, "あっちもゾロゾロつれてきやがり\nましたね…へんっ、このあたしが\nビビビビるとでもおお思うですか\n…お、お兄さん、どどどこです？", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (231, 5, "", "", 4, "vo_empress_106601_003", 2, "vo_empress_106601_003", "イノリ", 0, 106603, "…！　あたしと同じドラゴン族？\nボスをプリンセスナイトに従えて\nたとか…へんっ、信じねーです！\nまあボスより性悪そ…ぴゃああっ", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (232, 5, "", "", 4, "vo_empress_106601_004", 3, "vo_empress_106601_004", "イノリ", 106601, 106602, "ふっふっふ～ん！　熱い力が\nどんどん溢れてくるですよっ！\nさあ、懲らしめてやるですっ！\nおしりペンペンですよ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (233, 5, "", "", 4, "vo_empress_106701_001", 1, "vo_empress_106701_001", "ホマレ", 0, 106701, "ふふっ、強そうな子がいっぱいだね\nそれじゃあ、誰が一番か決めよっか\nヴィーちゃんのプリンセスナイトで\n歴代最強は誰なのかを、ね♪", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (234, 5, "", "", 4, "vo_empress_106701_002", 1, "vo_empress_106701_002", "ホマレ", 0, 106701, "ヴィーちゃんてば、そんな子たちと\n一緒にいるほうが楽しいんだ～？\nじゃ、私たちも見せつけないとだね\n遠慮なくやっちゃおう☆　あははっ", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (235, 5, "", "", 4, "vo_empress_106701_003", 2, "vo_empress_106701_003", "ホマレ", 0, 106703, "これが、ヴィーちゃんの本気…\nとってもとってもすごいなぁ\n怖がりだからこそ、そんなに\n強くなれちゃったのかな…", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (236, 5, "", "", 4, "vo_empress_106701_004", 3, "vo_empress_106701_004", "ホマレ", 106701, 106702, "残念だけど、ヴィーちゃん…\nもうゲームオーバーみたいだよ\nあなたとのどんなゲームも私には…\n全部ドキドキして、楽しかったな", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (237, 5, "", "", 4, "vo_empress_106801_001", 1, "vo_empress_106801_001", "ラビリスタ", 0, 106802, "毎度、予想を超える困難ばかり\n押し寄せてくるんだからさ～\nま、アタシと少年が居る以上、\n好きにはさせないよ、ってね！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (238, 3, 10000, 1, 4, "vo_empress_106801_002", 4005, "vo_empress_106801_002", "ラビリスタ", 0, 106801, "よりによって真那まで相手かぁ…\nこりゃ一筋縄じゃいかなそうだ\n誰に対応するかは任せるけど、\n真那を相手取るなら頼ってよ", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (239, 5, "", "", 4, "vo_empress_106801_003", 2, "vo_empress_106801_003", "ラビリスタ", 0, 106801, "当然、奥の手も用意してくるよね\n次から次へと用意周到だこと…\nとはいえこっちも負けられない\nこの難局の突破口を探すとしよう！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (240, 5, "", "", 4, "vo_empress_106801_004", 3, "vo_empress_106801_004", "ラビリスタ", 106801, 106802, "七冠…しかも幻境竜后が相手なら\n手は抜けそうにもないね\nはは、でもアタシたちならきっと\n乗り越えられーる！　だよね少年♪", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (241, 3, 10000, 1, 4, "vo_empress_107001_001", 4005, "vo_empress_107001_001", "ネネカ", 0, 107001, "真那…ふふ、こんなところで相対\nすることになるとは。いつぞやの\n借り、返してあげますよ。用意は\nいいですね？　マサキも、貴方も", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (242, 5, "", "", 4, "vo_empress_107001_002", 1, "vo_empress_107001_002", "ネネカ", 0, 107001, "数で私たちを圧倒しようなど…\n底の浅い戦略ですね。返り討ちに\nしてあげましょう…この世界を\nまだ失うわけにはいきませんから", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (243, 5, "", "", 4, "vo_empress_107001_003", 2, "vo_empress_107001_003", "ネネカ", 0, 107001, "この力…計算外ではありますが\nそれは予想外という意味では\nありません。ええ、楽しみましょう\n不可能を解く、方程式の探求を", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (244, 5, "", "", 4, "vo_empress_107001_004", 3, "vo_empress_107001_004", "ネネカ", 107001, 107002, "特等席で観察させてもらいましょう\n貴方の『心』という変数が\n『レジェンドオブアストルム』に\nどのような影響を与えるのかを…", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (245, 5, "", "", 4, "vo_empress_107101_001", 1, "vo_empress_107101_001", "クリスティーナ", 0, 107101, "クリスティーナさんのご登場だよ☆\nあっははは……☆　またとない宴だ\n心行くまで愉しもうじゃあないか\n血で血を洗うダンス…滾るな♪", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (246, 3, 10000, 1, 4, "vo_empress_107101_002", 4005, "vo_empress_107101_002", "クリスティーナ", 0, 107101, "真那さまがお出ましか…ワタシは\n本当に運がいいと見える♪　本気で\n刃を交える機会が巡ってくるなど\n願ってもない幸運だよ☆", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (247, 5, "", "", 4, "vo_empress_107101_003", 2, "vo_empress_107101_003", "クリスティーナ", 0, 107103, "…ここで退くなど興冷めだろう？\nたとえ足が竦んだとしても…退屈に\n食われるよりもよほどいい！\n最後まで愉しみつくしてやるさ…☆", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (248, 5, "", "", 4, "vo_empress_107101_004", 3, "vo_empress_107101_004", "クリスティーナ", 107101, 107102, "誤算だったなあ、『幻境竜后』\n他の者ならいざ知らず…\nキサマを殺せる唯一の力\n手にしたのはこの『誓約女君』だ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (249, 5, "", "", 4, "vo_empress_110801_001", 1, "vo_empress_110801_001", "クロエ", 0, 110801, "ざーす。世界を救う系の光バイトで\n来たんすけど…あ、説明とかは\n大丈夫っす。慣れてるんでノリで\n入れます─おのれ世界の敵め！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (250, 3, 10000, 1, 4, "vo_empress_110801_002", 4005, "vo_empress_110801_002", "クロエ", 0, 110801, "なっつ、狐のねえさんいるじゃん\nまだ現役で悪モンやってたんだ\nてか中ボスポジに降格してるくね？\n世界の敵界隈、意外とせちがれーな", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (251, 5, "", "", 4, "vo_empress_110801_003", 2, "vo_empress_110801_003", "クロエ", 0, 110803, "なんかヤベーの出てきたな…\nこのカンジ、若干最悪っていうか\nぶっちゃけ流れ変わったくない？\nこっから捲るのは…結構ダルいわ", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (252, 5, "", "", 4, "vo_empress_110801_004", 3, "vo_empress_110801_004", "クロエ", 110801, 110802, "ちょ、聞いて敵、ウケんだけど\nなんかうち主人公だったみたいだわ\n山場でヒロインに力託され系のやつ\nてわけで、勝ち確いただきでーす", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (253, 5, "", "", 4, "vo_empress_110901_001", 1, "vo_empress_110901_001", "チエル", 0, 110901, "ちぇるーん☆　ボス敵のみんな～！\n初めまして＆お久しブリリアント！\n世界の美少女ちえるんでっす！\n今からぼっこぼこにしてあげるね！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (254, 5, "", "", 4, "vo_empress_110901_002", 1, "vo_empress_110901_002", "チエル", 0, 110901, "クリスＰの敵はカルミナの敵！\nカルミナの敵はなかよし部の敵！\nツアー全通めざして戦います！\n現場の平和はチエルが守る！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (255, 5, "", "", 4, "vo_empress_110901_003", 2, "vo_empress_110901_003", "チエル", 0, 110903, "あ、あのう…ヤバくないです？\n敵のねえさん、急に年末歌合戦の\nラスボス衣装みたくなりましたけど\nえ、どーしよ…揚げます白旗？", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (256, 5, "", "", 4, "vo_empress_110901_004", 3, "vo_empress_110901_004", "チエル", 110901, 110902, "世界の敵さん、ごめんちゃい！\nなんか愛だか絆だかの超理論的な\nアレでチエル覚醒しちゃいました！\nちぇるっと終わらせてあげますね！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (257, 5, "", "", 4, "vo_empress_111001_001", 1, "vo_empress_111001_001", "ユニ", 0, 111001, "世界の危機だって？　何度目だね？\nざまあみろだよ、勝手に滅べば…\nなに、地球の危機？　この箱庭の\n話ではなく？　何ソレ一大事！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (258, 5, "", "", 4, "vo_empress_111001_002", 1, "vo_empress_111001_002", "ユニ", 0, 111001, "お、おい…敵が多すぎないか…？\n端の方でわちゃわちゃしてるだけの\n数合わせ要員として来たのだが…\nどういう事だ、聞いてた話と違うぞ", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (259, 5, "", "", 4, "vo_empress_111001_003", 2, "vo_empress_111001_003", "ユニ", 0, 111003, "あばば…なんだ、あの奇怪な姿は…\nあれが理系をこじらせた者の末路か\n宇宙暗黒理系女…どうしてあんなに\nなるまで放っておいたんだ…", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (260, 5, "", "", 4, "vo_empress_111001_004", 3, "vo_empress_111001_004", "ユニ", 111001, 111002, "はん、驕ったな理系の女王よ\n世界は君が思うほど四角くない\n高機能計算機の弾いた数字ごときで\nぼくと彼の行間までは測れまいよ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (261, 5, "", "", 4, "vo_empress_118001_001", 1, "vo_empress_118001_001", "クレジッタ", 0, 118001, "ですからわたくしは商人で、\n戦いなどは不向き…などと\n言ってる場合ではありませんわね！\n参りますわよ、我が陛下のために！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (262, 5, "", "", 4, "vo_empress_118001_002", 1, "vo_empress_118001_002", "クレジッタ", 0, 118003, "ああもうはあもう、あっちこっち\n滅茶苦茶にしてくださってからに！\n復興費用の賠償はどなたに\n請求すればよろしいのかしら！？", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (263, 5, "", "", 4, "vo_empress_118001_003", 2, "vo_empress_118001_003", "クレジッタ", 0, 118003, "でっか！？　でっっっっか！！！\n幻境竜后でしたかしら！？\nなんなんですのあの高層建築な方、\n建築基準法違反ですわよ～っ！？", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (264, 5, "", "", 4, "vo_empress_118001_004", 3, "vo_empress_118001_004", "クレジッタ", 118001, 118002, "ホーッホッホッホ！　幻境竜后さん\n貴方にはいらっしゃるのかしら！\n利害でなくその理想のために\n命を賭ける、真実の忠臣が！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (265, 5, "", "", 4, "vo_empress_118101_001", 1, "vo_empress_118101_001", "ランファ", 0, 118101, "恐ろしくて強そうな音が…たくさん\nでも…きっと、大丈夫。あなたや、\nミソラちゃん…みんなが一緒で…\nあたたかい音も、たくさんだもの…", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (266, 5, "", "", 4, "vo_empress_118101_002", 1, "vo_empress_118101_002", "ランファ", 0, 118101, "緊張、してる…？　そ、それなら、\nわたしに、任せて…わたし、歌を、\n歌うわね…聴けばきっと、いつも\n通りの力を、出せると思うから…", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (267, 5, "", "", 4, "vo_empress_118101_003", 2, "vo_empress_118101_003", "ランファ", 0, 118103, "お、音と声が、すごい…\nなんて…なんて恐ろしいのかしら…\n…？　で、でも…この音。\n幻境竜后も、恐怖…している…？", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (268, 5, "", "", 4, "vo_empress_118101_004", 3, "vo_empress_118101_004", "ランファ", 118101, 118102, "わたしの歌が、どれほど役立つかは\nわからない…そ、それでもっ、\nあなたの力になりたいの…だから\nわたし、精一杯、歌うわね…", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (269, 3, 10000, 1, 4, "vo_empress_118201_001", 4005, "vo_empress_118201_001", "ミソラ", 0, 118201, "わー、ミロクさんや覇瞳皇帝さんも\nいるじゃないですか★\nそれじゃあわたしのガトリングで\nご挨拶といきましょっか♪", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (270, 5, "", "", 4, "vo_empress_118201_002", 1, "vo_empress_118201_002", "ミソラ", 0, 118201, "騎士さんと力を合わせればどんな\n敵もほにゃららら～★　って感じで\nなんとかなると思うんですよねー\nほら、主人公補正ってやつで♪", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (271, 5, "", "", 4, "vo_empress_118201_003", 2, "vo_empress_118201_003", "ミソラ", 0, 118202, "復讐って、イイコトですかね？\n悪いコトですかね？まぁとりあえず\nぶっ壊してから考えましょうか\nね、幻境竜后さん─", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (272, 5, "", "", 4, "vo_empress_118201_004", 3, "vo_empress_118201_004", "ミソラ", 118201, 118202, "騎士さんに選んでもらっちゃいまし\nたし、いらない縁とはバイバイした\nいんですよねー♪　ってわけで、\nここで終わりにさせてもらいます★", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (273, 5, "", "", 4, "vo_empress_118501_001", 1, "vo_empress_118501_001", "カリン", 0, 118501, "みなさんの力を信じて、\n私も全力でサポートします\n連携と創意工夫があれば、きっと\nこの難局も乗り越えられます！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (274, 5, "", "", 4, "vo_empress_118501_002", 1, "vo_empress_118501_002", "カリン", 0, 118502, "過去最大級の強敵が現れました！\nギルド管理協会を代表して…\nあなたに討伐を依頼します！\n報酬はお望みのままに、ですよ♪", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (275, 5, "", "", 4, "vo_empress_118501_003", 2, "vo_empress_118501_003", "カリン", 0, 118503, "…っ。さすがの強敵ですね…\nだからこそ、焦りは禁物…です\nあらゆる事態を想定して、ギルドの\nみなさんを支援するのが私の仕事…", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (276, 5, "", "", 4, "vo_empress_118501_004", 3, "vo_empress_118501_004", "カリン", 118501, 118502, "あなたと共に進めば\nどんな壁も越えられます\n私の、大切な人の無事を信じて…\n今こそ全力を尽くします！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (277, 5, "", "", 4, "vo_empress_118601_001", 1, "vo_empress_118601_001", "ネビア", 0, 118601, "あんな奴らを野放しにしてたら\nこの世界が滅茶苦茶にされちゃう！\nでもまぁこれはこれでチャンスよ♪\n最っ高の悪戯の標的にしてあげる！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (278, 5, "", "", 4, "vo_empress_118601_002", 1, "vo_empress_118601_002", "ネビア", 0, 118601, "私はただのガイド妖精、みんなに\n比べれば大した力も持ってない…\nでも悪戯妖精なりの意地があんのよ\nあいつらに一泡吹かせてやるわ♪", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (279, 5, "", "", 4, "vo_empress_118601_003", 2, "vo_empress_118601_003", "ネビア", 0, 118603, "幻境竜后、なんて力の持ち主なの\n正直きっついわ…でもまだやれる\n私はデータよ、壊れたって\nあんたを守る壁くらいにはなれる…", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (280, 5, "", "", 4, "vo_empress_118601_004", 3, "vo_empress_118601_004", "ネビア", 118601, 118602, "覚悟しなさいっ！\n出来損ないの悪戯妖精をなめたら\n痛い目に遭うって教えてあげる\nさぁ、最高のショーの始まりよ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (281, 5, "", "", 4, "vo_empress_122301_001", 1, "vo_empress_122301_001", "ヴァンピィ", 0, 122303, "むー！　いたずらっこの暴れんぼ\nさんたちは、ヴァンピィちゃんが\nきつーくおしおきしちゃうよ！\n真祖のおつとめですから！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (282, 5, "", "", 4, "vo_empress_122301_002", 1, "vo_empress_122301_002", "ヴァンピィ", 0, 122302, "けんぞくはヴァンピィちゃんの\n背中に隠れてなさいっ。え？\n背中を守りたい？　うん、それなら\nよろしい！　一緒だよ、けんぞく！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (283, 5, "", "", 4, "vo_empress_122301_003", 2, "vo_empress_122301_003", "ヴァンピィ", 0, 122303, "幻境竜后？　ふーんだ！\nベスちゃんのほーが、ずーっと\n強くてカッコいいですし！\nいくよっ、けんぞくぅ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (284, 5, "", "", 4, "vo_empress_122301_004", 3, "vo_empress_122301_004", "ヴァンピィ", 122301, 122302, "ここはみんなの『いばしょ』！\n壊しちゃうなんて、許さないもん\nヴァンピィちゃん、本気で怒ったよ\nやっちゃうよ、けんぞく！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (285, 5, "", "", 4, "vo_empress_123001_001", 1, "vo_empress_123001_001", "アメス", 0, 123002, "ほら、あんたは余計な心配しないの\nあいつらに好き勝手させないように\n全力でぶつかっていくだけよ\nあたしたちの未来のためにね♪", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (286, 5, "", "", 4, "vo_empress_123001_002", 1, "vo_empress_123001_002", "アメス", 0, 123001, "…あの連中も強くてやばいけど…\n一番やばいのは、こんなにたくさん\n女の子の知り合いがいる\nあんたかもしれないわね…", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (287, 5, "", "", 4, "vo_empress_123001_003", 2, "vo_empress_123001_003", "アメス", 0, 123003, "なんて相手なの…さすがに想定を\n超えてるわよ…こんなの卑怯よね\nだからってここで逃げやしないわよ\nせめて、あんたを守るくらいは…！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (288, 5, "", "", 4, "vo_empress_123001_004", 3, "vo_empress_123001_004", "アメス", 123001, 123002, "敵がどれだけ強くたって関係ないわ\nあんたの行く道はあたしが照らす\n迷ったらあたしを見なさい\nどこまでだって導いてあげる！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (289, 5, "", "", 4, "vo_empress_123301_001", 1, "vo_empress_123301_001", "ネア", 0, 123301, "『レギオンウォー』思い出すな～\nあん時は敵側だったけどー\n今回は騎士きゅんたちの隣で\nネアおねえちゃんもがんばるぞ～♡", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (290, 5, "", "", 4, "vo_empress_123301_002", 1, "vo_empress_123301_002", "ネア", 0, 123301, "だる～、激ヤバなテキばっかじゃん\n騎士きゅんパワー充電しねーと\nおねえちゃんもギリギリかもー\nとりま、ちゅっちゅ♡　してい？", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (291, 5, "", "", 4, "vo_empress_123301_003", 2, "vo_empress_123301_003", "ネア", 0, 123303, "激ヤバドラゴン、ガチしんどー…\nま、だからって負ける気ねーけど\nこーゆう時こそ、スライムの\n粘り強さの見せ所っしょ～　ね♪", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (292, 5, "", "", 4, "vo_empress_123301_004", 3, "vo_empress_123301_004", "ネア", 123301, 123302, "ンフフフフ～♪　今のアタシ、\n騎士きゅんと一心同体ってやつ～？\nめちゃめちゃアガるわ～♪\n愛の力パねぇ～♡", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (293, 5, "", "", 4, "vo_empress_126401_001", 1, "vo_empress_126401_001", "クローチェ", 0, 126401, "ビーッ！　ビーッ！\nあっちもこっちもそっちも\n強そうな人たちでいっぱいですっ！\nセンサーが壊れちゃいそう～っ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (294, 5, "", "", 4, "vo_empress_126401_002", 1, "vo_empress_126401_002", "クローチェ", 0, 126401, "世界が大変なことになってますっ！\nでもわたしたちは今までだって、\n大変な戦いを乗り越えてきましたっ\nきっと…ううん、絶対勝てますっ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (295, 5, "", "", 4, "vo_empress_126401_003", 2, "vo_empress_126401_003", "クローチェ", 0, 126403, "ビビービビビーッ！　…ひゃあっ！\nセンサーが壊れちゃいました…！\nしかも、照準が震えちゃって…\n…これが…この感情が、恐怖…？", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (296, 5, "", "", 4, "vo_empress_126401_004", 3, "vo_empress_126401_004", "クローチェ", 126401, 126402, "今のわたしたちに、怖いものなんて\nありませんっ！　敵さんがどんなに\n強くても…わたしとナイトさんの\n特別なパワーは、もっと強いです！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (297, 5, "", "", 4, "vo_empress_126501_001", 1, "vo_empress_126501_001", "ライラエル", 0, 126501, "ジオ・テオゴニアの姫として\nこの星に生きる一個として\nこれ以上の蹂躙を許すわけには\nいきません。そうですね？　騎士", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (298, 3, 10000, 1, 4, "vo_empress_126501_002", 4002, "vo_empress_126501_002", "ライラエル", 0, 126506, "穢らわしい、色狂いの山羊めが\n我が従僕を傀儡としてくれた借り、\n兆倍──否、京倍にして\n返してくれようぞ。崩雷夜天！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (299, 5, "", "", 4, "vo_empress_126501_003", 2, "vo_empress_126501_003", "ライラエル", 0, 126503, "幻境竜后。迷いなく、圧倒的な力で\nわたしたちの調和を滅しようとする\nそんな力を、認めたくはないのに…\nなんて、困難な戦いなのでしょう…", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (300, 5, "", "", 4, "vo_empress_126501_004", 3, "vo_empress_126501_004", "ライラエル", 126501, 126502, "この星には、あなたがいる…\n悪辣な侵略者と戦う理由など、\nただそれだけで十分です\n守りましょう。わたしたちの世界を", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (301, 3, 10000, 1, 4, "vo_empress_127701_001", 4002, "vo_empress_127701_001", "リンド", 0, 127701, "あそこにヴルムを傷つけた人が…！\n…騎士さん、絶対勝ちましょうね\nあの人たちのやったこと、私\n絶対ぜったい許しませんから！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (302, 5, "", "", 4, "vo_empress_127701_002", 1, "vo_empress_127701_002", "リンド", 0, 127701, "騎士さんたちと出会えたこの世界を\n悪いことになんか使わせません\n作り物だなんて信じられませんけど\n失っちゃいけないものはわかります", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (303, 5, "", "", 4, "vo_empress_127701_003", 2, "vo_empress_127701_003", "リンド", 0, 127703, "まだこんな力が残ってるの…！？\n考えなきゃ、私にできること…\n何か…何かないの…！？\nまた私、何もできないの…？", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (304, 5, "", "", 4, "vo_empress_127701_004", 3, "vo_empress_127701_004", "リンド", 127701, 127702, "あなたが側にいてくれるから、\n私もこうして戦えます\nチョロいって言われてもいいです\n私にとって、大切なひとですから", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (305, 5, "", "", 4, "vo_empress_127801_001", 1, "vo_empress_127801_001", "ヴルム", 0, 127801, "…正直、サボりとかじゃなくて…\nぜんぜん身体はきついです。でも…\n姉貴やみんなと過ごすこの世界は\n誰にも壊させやしませんから…！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (306, 3, 10000, 1, 4, "vo_empress_127801_002", 4002, "vo_empress_127801_002", "ヴルム", 0, 127801, "騎士さん…アルシャトのこと\nあたしにも一発殴らせてください\nふざけた真似してくれたお礼…\n倍にして返してやりますよ", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (307, 5, "", "", 4, "vo_empress_127801_003", 2, "vo_empress_127801_003", "ヴルム", 0, 127803, "冗談きついです、こんなの…\n勝てっこないじゃないですか\nあたしだってドラゴン族なのに\nこれほどまでに差があるだなんて…", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (308, 5, "", "", 4, "vo_empress_127801_004", 3, "vo_empress_127801_004", "ヴルム", 127801, 127802, "もう後先考えずにいきますよ\n面倒見てくれる人がここにいるので\nあたしと騎士さんが揃えば\n無敵だってとこ見せてやります", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (309, 3, 10000, 1, 4, "vo_empress_129001_001", 4005, "vo_empress_129001_001", "エリス", 0, 129001, "覇瞳皇帝…わたしの邪魔をするなら\nかつてのように、消去するだけ\nミロクも…わたしを草野優衣の\n複製と呼んだこと、後悔させてやる", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (310, 5, "", "", 4, "vo_empress_129001_002", 1, "vo_empress_129001_002", "エリス", 0, 129001, "管理者の座は失っても\nわたしの意志は揺らがない…\n騎士クンの物語を紡ぐために…\nそれが、わたしの全てだから", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (311, 5, "", "", 4, "vo_empress_129001_003", 2, "vo_empress_129001_003", "エリス", 0, 129003, "これが七冠、幻境竜后の全力…\n管理者だったかつてのわたしを、\n超えるほどの脅威…でも、\n騎士クンだけは、守ってみせる…", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (312, 5, "", "", 4, "vo_empress_129001_004", 3, "vo_empress_129001_004", "エリス", 129001, 129002, "孤独も絶望も越えてきた\nもうどんな闇にも迷わない\n騎士クンが隣にいる限り\nわたしは、負けない", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (313, 5, "", "", 4, "vo_empress_129601_001", 1, "vo_empress_129601_001", "アネモネ", 0, 129601, "リアを──媛を、傷つけたひとたち\n笑ってられるのも今だけです──\nアルラウネの棘の鋭さ、\n教えてあげますから──", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (314, 5, "", "", 4, "vo_empress_129601_002", 1, "vo_empress_129601_002", "アネモネ", 0, 129601, "騎士のひと──背中は、任せます\n貴方のこと、\n媛と同じくらい、信じてるので──\n自分でも、びっくりですけど", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (315, 5, "", "", 4, "vo_empress_129601_003", 2, "vo_empress_129601_003", "アネモネ", 0, 129603, "私、ずっと抗ってきたんです\nそのために、強くなったはず──\nだから──諦めたく、ないです…", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (316, 5, "", "", 4, "vo_empress_129601_004", 3, "vo_empress_129601_004", "アネモネ", 129601, 129601, "体が熱くて、思考がまとまらなくて\nなのに負ける気がしない──なんて\nよくわからないです。どうしてか、\n後で教えてください──騎士のひと", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (317, 5, "", "", 4, "vo_empress_129701_001", 1, "vo_empress_129701_001", "ネフィ＝ネラ", 0, 129701, "難敵強敵揃い踏みなれど\nわっちらが退く理はありんせん\n騎士殿や、手を携えて此度の争乱\n鎮めて見せましょう也", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (318, 5, "", "", 4, "vo_empress_129701_002", 1, "vo_empress_129701_002", "ネフィ＝ネラ", 0, 129701, "今のわっちが萎弱であろうとて\n貴様等如き梟悪に斃される訳には\nゆかぬ也。再び足甲を舐めさせ\n地に臥すまで仕置きを致しんしょう", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (319, 5, "", "", 4, "vo_empress_129701_003", 2, "vo_empress_129701_003", "ネフィ＝ネラ", 0, 129703, "我が矜持『不退転』─如何なる敵で\nあろうとも揺らぐ仕儀はなし。斯様\nな邪竜程度、退けむと思い侍りしが\n─難儀な由、残念至極─…", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (320, 5, "", "", 4, "vo_empress_129701_004", 3, "vo_empress_129701_004", "ネフィ＝ネラ", 129701, 129702, "参りまする也、騎士殿や\n懼るること等何一つ御座りんせん\n唯わっちらの勇儀を以て、此の星の\n明日を再び…掌中に致しんしょう", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (321, 3, 10000, 1, 4, "vo_empress_130001_001", 4003, "vo_empress_130001_001", "ヤマト", 0, 130001, "─おや、フレイヤじゃないか\nずいぶん様変わりしたようだが\n今の方がアタシとしちゃ好みだね\nお礼参りのしがいもあるってもんさ", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (322, 5, "", "", 4, "vo_empress_130001_002", 1, "vo_empress_130001_002", "ヤマト", 0, 130001, "…フゥン？　あっちもこっちも\n『王家の装備』を持ってるらしいね\n宝の山ってのはこのことかい\nまとめて搔っ攫ってやろうかね…！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (323, 5, "", "", 4, "vo_empress_130001_003", 2, "vo_empress_130001_003", "ヤマト", 0, 130003, "ちっ…、幻境竜后つったかい\n世界を奪おうってのも冗談じゃ\nなさそうだ。…ワカナ、フブキ…\nお前たちだけでも、逃げな…", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (324, 5, "", "", 4, "vo_empress_130001_004", 3, "vo_empress_130001_004", "ヤマト", 130001, 130002, "アタシらの住み家を奪おうだぁ？\nハッ、笑わせてくれるね\n盗賊は盗むモンであって、\n盗まれるモンじゃあないンだよ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (325, 5, "", "", 4, "vo_empress_130101_001", 1, "vo_empress_130101_001", "ワカナ", 0, 130101, "つ、強そうな人たちがたくさん…\nなのに姉さんもフブキちゃんも\nやる気満々だし…\nわたし、どうすればいいのぉ～っ", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (326, 5, "", "", 4, "vo_empress_130101_002", 1, "vo_empress_130101_002", "ワカナ", 0, 130101, "きっと、長期戦になりますよね…\nあ、あの…ご飯、食べませんか？\nお腹が空くといけないと思って、\n作ってきたので…よろしければっ", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (327, 5, "", "", 4, "vo_empress_130101_003", 2, "vo_empress_130101_003", "ワカナ", 0, 130103, "む…むりっ！　無理ですよ～っ！\nあんなおっきいドラゴンなんて、\n勝てるわけないじゃないですかっ\nに、逃げちゃいましょ、ねっ…！？", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (328, 5, "", "", 4, "vo_empress_130101_004", 3, "vo_empress_130101_004", "ワカナ", 130101, 130102, "と、盗られるぐらいなら盗るのが\n【バンディ・シスターズ】流ですっ\n騎士さん、わたしたちの未来を\n掴み取りにいきましょう…っ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (329, 5, "", "", 4, "vo_empress_130201_001", 1, "vo_empress_130201_001", "フブキ", 0, 130201, "だる～、ささっと片付けてきてよ～\nムリ？　知ってる～だってザコザコ\nお兄さんだもんね♪　しょーがない\n助けてあげよっかな～？きゃはは♡", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (330, 5, "", "", 4, "vo_empress_130201_002", 1, "vo_empress_130201_002", "フブキ", 0, 130201, "あの陰気ダサダサメガネさー、\n仲間集めてチョーシ乗ってねー？\nザコは何匹集まったってザコだって\nフブキちゃんが教えてあげまーす♪", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (331, 5, "", "", 4, "vo_empress_130201_003", 2, "vo_empress_130201_003", "フブキ", 0, 130203, "ふぇぇ…まじムリ、アイツムリ～！\n全然ラスボスってカンジじゃん！？\nぼくお家かえるぅ～っ！\nお兄さんも一緒にかえろっ、ねっ？", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (332, 5, "", "", 4, "vo_empress_130201_004", 3, "vo_empress_130201_004", "フブキ", 130201, 130202, "お兄さん、やる気漲っちゃってる？\nだよねー、世界が滅んじゃったら\nぼくとも永遠のお別れなんだし？\n必死になるのもトーゼンっしょ～♡", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (333, 5, "", "", 4, "vo_empress_130901_001", 1, "vo_empress_130901_001", "クルル", 0, 130901, "はわっ！？　すっごくすっごく\n悪そうな人達いっぱいですますぅ！\nかばばん君、警備員モードです！\nぴっぴーーーー！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (334, 5, "", "", 4, "vo_empress_130901_002", 1, "vo_empress_130901_002", "クルル", 0, 130901, "この戦いが終わったら、みなさんと\nパークで凱旋パレードですぅ♪\n…ふぇっ？\n気が早いですますか？", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (335, 5, "", "", 4, "vo_empress_130901_003", 2, "vo_empress_130901_003", "クルル", 0, 130903, "はわわっ！　幻境竜后さん、\n強そうすぎですっ…でもっ！\nやっと再建したパークも世界も\nぜったい壊させないですよ～っ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (336, 5, "", "", 4, "vo_empress_130901_004", 3, "vo_empress_130901_004", "クルル", 130901, 130902, "ヒーローさんのこと、\nクルルの全部でお助けしますです！\nジオ・テオゴニアでも、どんな世界\nでも…ずっと、ず～っとですっ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (337, 5, "", "", 4, "vo_empress_132301_001", 1, "vo_empress_132301_001", "ルイズマリー", 0, 132301, "なっなんなのよこいつらっ！\nダーリンとの恋路を邪魔する気…？\nそんなことさせないわ…だって、\n二人の恋はエターナルですからっ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (338, 5, "", "", 4, "vo_empress_132301_002", 1, "vo_empress_132301_002", "ルイズマリー", 0, 132301, "愛情×愛情＝無限大…\n遂に錬金術の神髄に辿り着いたわ…\nさあ…お見舞いしてやりましょう！\n私とダーリンの究極錬成をっ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (339, 5, "", "", 4, "vo_empress_132301_003", 2, "vo_empress_132301_003", "ルイズマリー", 0, 132303, "あ、あなたがどんなに強くても、\n私は逃げないわ！　ダーリンに\nちょっかいかける奴は絶対に\n許さないって決めてるから…っ！！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (340, 5, "", "", 4, "vo_empress_132301_004", 3, "vo_empress_132301_004", "ルイズマリー", 132301, 132302, "悪いけど速攻で終わらせちゃうわ！\n早く帰ってダーリンと心行くまで\n破廉恥な乳繰り合い…じゃなくて！\n愛を確かめ合うんだからっ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (341, 5, "", "", 4, "vo_empress_132401_001", 1, "vo_empress_132401_001", "イロハ", 0, 132401, "わわっ、敵がいっぱい！\nこれがクワガタだったら最高…よし\n新種のクワガタって事にしちゃお！\nあははっ！　待て待て～っ！！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (342, 5, "", "", 4, "vo_empress_132401_002", 1, "vo_empress_132401_002", "イロハ", 0, 132401, "あはは、まだまだ出てくるね～！\nなら新しい技いっぱい\n試しちゃおっか…さあ、いくよ！\n──イスルギ流奥義っ！！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (343, 5, "", "", 4, "vo_empress_132401_003", 2, "vo_empress_132401_003", "イロハ", 0, 132401, "あのおねーさんもなかなか良いツノ\n持ってるねえ♪　イロハが勝ったら\nルイちゃんと二人でクワガタ相撲\nごっこやってもらおっと！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (344, 5, "", "", 4, "vo_empress_132401_004", 3, "vo_empress_132401_004", "イロハ", 132401, 132402, "おねーさんがどんなに強くたって\nイロハは絶対に負けない！\nおじちゃんが見ててくれてる時の\nイロハは、サイキョーなんだから！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (345, 5, "", "", 4, "vo_empress_132501_001", 1, "vo_empress_132501_001", "ソノ", 0, 132501, "いや無理無理、戦いとか苦手過ぎる\n…でも君となら、奇跡起こせるかも\n…うわやば、今の忘れて\n若者みたいなこと言っちゃったよ…", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (346, 5, "", "", 4, "vo_empress_132501_002", 1, "vo_empress_132501_002", "ソノ", 0, 132501, "敵、まだいっぱいいるじゃん…\nはあ…残業したくないけど頑張るか\n全部終わったら君からのマッサージ\n期待しとくから、ね", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (347, 5, "", "", 4, "vo_empress_132501_003", 2, "vo_empress_132501_003", "ソノ", 0, 132503, "はあ…はあ…幻境竜后だっけ？\nルイちゃんの錬金術より\n出鱈目な強さだね…！\nでもまだまだ諦めない…いくよ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (348, 5, "", "", 4, "vo_empress_132501_004", 3, "vo_empress_132501_004", "ソノ", 132501, 132502, "こんなに強い敵が相手でも\n諦めなきゃ勝てるんだって\n教えてくれたのは君だよ\nふふ…ありがとね、若者♪", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (349, 5, "", "", 4, "vo_empress_133001_001", 1, "vo_empress_133001_001", "グレイス", 0, 133001, "うーわ。あっちもこっちも\nボス級だらけじゃないですか\nま、ヴァイオレット姫には\n指一本触れさせませんけどね", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (350, 3, 10000, 1, 4, "vo_empress_133001_002", 4001, "vo_empress_133001_002", "グレイス", 0, 133003, "リーザ…今度こそ、決着の時ね\nいくら頭数を揃えても私は…いえ\n私と騎士氏は絶対に負けないわ\nこの槍で、冥界に送り返してあげる", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (351, 5, "", "", 4, "vo_empress_133001_003", 2, "vo_empress_133001_003", "グレイス", 0, 133003, "ぐっ…圧倒的ですね『幻境竜后』\nですが…決してあきらめません\n私には、生きていてほしい人が\nたくさんいますので…！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (352, 5, "", "", 4, "vo_empress_133001_004", 3, "vo_empress_133001_004", "グレイス", 133001, 133002, "とてつもない強敵を前にしてるのに\nまるで恐怖心を感じません…\n…恋とは、心霊現象よりも\n不思議なものらしいですよ", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (353, 5, "", "", 4, "vo_empress_133101_001", 1, "vo_empress_133101_001", "ヴァイオレット", 0, 133101, "恐るべき方々ばかりです…\nですがわたくしは絶対に退きません\nジオ・ニヴルヘルの姫として\nこの世界を守ると決めたのです！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (354, 3, 10000, 1, 4, "vo_empress_133101_002", 4001, "vo_empress_133101_002", "ヴァイオレット", 0, 133101, "リーザ…どうしてもわたくしたちの\n前に立ちはだかるというのですね\nならばわたくしも覚悟を決めました\nこの手であなたを、倒します…！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (355, 5, "", "", 4, "vo_empress_133101_003", 2, "vo_empress_133101_003", "ヴァイオレット", 0, 133103, "これが、彼女の本気の力…！\n異質で…故に、とても寂しい…\n本当の意味で彼女に届く声が、\nこの世界に存在するのでしょうか…", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (356, 5, "", "", 4, "vo_empress_133101_004", 3, "vo_empress_133101_004", "ヴァイオレット", 133101, 133102, "あなたとの「繋がり」がある限り\n死が牙を剥くことはありません\n手を取り合い、共に参りましょう\nわたくしたちの未来のために！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (357, 5, "", "", 4, "vo_empress_133601_001", 1, "vo_empress_133601_001", "メドゥーサ", 0, 133601, "フンっ、次から次へと…！　なら\n思う存分、大暴れしてやるから♪\nやっちゃうわよ、メドゥシアナ！\nアンタも！！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (358, 5, "", "", 4, "vo_empress_133601_002", 1, "vo_empress_133601_002", "メドゥーサ", 0, 133601, "どこの誰だか知らないけれど、\nアタシの魔眼でまとめて石に…って\nきゃああああ！　こんなバケモン級\nなら先に教えときなさいよ～っ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (359, 5, "", "", 4, "vo_empress_133601_003", 2, "vo_empress_133601_003", "メドゥーサ", 0, 133603, "な…なんなの、アイツの『眼』…\nでもねっ、アタシはメドゥーサ\nゴルゴーンの、お姉ちゃんの妹よ！\n睨みあいで負けるわけがないわ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (360, 5, "", "", 4, "vo_empress_133601_004", 3, "vo_empress_133601_004", "メドゥーサ", 133601, 133602, "知ってる？　蛇って執念深いのよ\nこの『眼』で見つけてやったわ\n幻境竜后、アンタが一番恐れること\nアタシとこいつが手をつなぐこと！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (361, 5, "", "", 4, "vo_empress_134701_001", 1, "vo_empress_134701_001", "ホウオウ", 0, 134701, "この大地と大空を守るため、\n人の子らだけに任せてはおけません\n鳳凰のはばたきで、その野望ごと\n跡形もなく吹き飛ばしましょう！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (362, 5, "", "", 4, "vo_empress_134701_002", 1, "vo_empress_134701_002", "ホウオウ", 0, 134701, "さあ皆さん、ここが正念場です！\n私がいれば楽勝圧勝間違いなし！\n…えっ？　私が先頭？　えーと…\nあっちょっと待って押さないで！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (363, 5, "", "", 4, "vo_empress_134701_003", 2, "vo_empress_134701_003", "ホウオウ", 0, 134703, "羽が散って、ちっ、力が…\n幻境竜后、やるではないですか…\nしかし、私も不死鳥と呼ばれた身…\nただでやられは…ぴ、ぴよぉぉ～…", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (364, 5, "", "", 4, "vo_empress_134701_004", 3, "vo_empress_134701_004", "ホウオウ", 134701, 134702, "幻境竜后、でしたか？\nあなたも運のない方ですね\n今の私は輪廻史上最強の鳳凰\nその鱗一つ残さず焼き尽くします！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (365, 5, "", "", 4, "vo_empress_134901_001", 1, "vo_empress_134901_001", "カノン", 0, 134901, "ヲ～ッホッホ！　どいつもこいつも\n大層なおツラ構えしてますけどぉ？\nあたくし様の敵じゃありませんわ！\nほら馬ボーン！　お強化なさいな！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (366, 5, "", "", 4, "vo_empress_134901_002", 1, "vo_empress_134901_002", "カノン", 0, 134901, "いってぇ～ですわ！　あたくし様の\nお美しいお肌を傷つけましたわね！\nまとめてお成敗して差し上げますわ\nついてらっしゃいな！　馬ボーン！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (367, 5, "", "", 4, "vo_empress_134901_003", 2, "vo_empress_134901_003", "カノン", 0, 134903, "なんてタマですの…アースハイドラ\nよりデカいなんて聞いてませんわ！\nでも…ここでお尻尾巻いて逃げる\nなら、死んだ方がマシですわ…！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (368, 5, "", "", 4, "vo_empress_134901_004", 3, "vo_empress_134901_004", "カノン", 134901, 134902, "幻境竜后とやら、お覚悟なさいな\nあたくしと馬ボーンの前に立つなど\n100億万年お早いですわ！\n華麗にお成敗して差し上げますわ♪", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (369, 5, "", "", 4, "vo_empress_135501_001", 1, "vo_empress_135501_001", "アイラ", 0, 135501, "来たね、お姉さんの出番ってやつ♪\nキミと一緒に戦えるなんて、あたし\nテンション最高潮だよ！　あははっ\nさ、思いっきり暴れちゃおっか！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (370, 3, 10000, 1, 4, "vo_empress_135501_002", 4005, "vo_empress_135501_002", "アイラ", 0, 135501, "あれが…覇瞳皇帝のオリジナルだね\nま、関係ないや。本物でも偽物でも\n今度こそ決着つけてあげるから！\nお姉さんの拳…燃え盛ってるよー！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (371, 5, "", "", 4, "vo_empress_135501_003", 2, "vo_empress_135501_003", "アイラ", 0, 135503, "幻境竜后…とんでもない相手だね\nあたしの拳だって届かないかも…\nそれでも、燃え尽きるまで戦うよ\nキミが信じてくれてる限り、ね！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (372, 5, "", "", 4, "vo_empress_135501_004", 3, "vo_empress_135501_004", "アイラ", 135501, 135502, "キミがいれば怖いものなし！\nお姉さん今、燃えに燃えてるよっ\n太陽より熱く燃える拳で…\n全部まとめてぶっ飛ばす！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (373, 5, "", "", 4, "vo_empress_135601_001", 1, "vo_empress_135601_001", "シナツ", 0, 135601, "どれほどの逆風の中にいても、\n諦めてはならない…そうだろう？\nかつて私が、他でもないキミたちに\nそう教えてもらったんだ…", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (374, 5, "", "", 4, "vo_empress_135601_002", 1, "vo_empress_135601_002", "シナツ", 0, 135601, "私はこの世界の人々と出会い、\n失ったはずの希望を見つけられた\n今度は私が、皆に希望を届ける番だ\nこの刃、存分に振るわせてくれ", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (375, 5, "", "", 4, "vo_empress_135601_003", 2, "vo_empress_135601_003", "シナツ", 0, 135603, "幻境竜后…私たちの世界を創造し、\nそして滅ぼそうとした張本人か…！\nその力がどんなに強大だとしても…\n私は…絶対に逃げたりなどしない！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (376, 5, "", "", 4, "vo_empress_135601_004", 3, "vo_empress_135601_004", "シナツ", 135601, 135602, "私の刃に、もはや一片の曇りもない\n皆と生きる未来を守り抜くために\n戦いつづける…ただそれだけだ\n─道を阻む者は全て斬り伏せる！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (377, 3, 10000, 1, 4, "vo_empress_135801_001", 4001, "vo_empress_135801_001", "ユキノ", 0, 135801, "リ、リ、リーザちゃ…！\nリーザちゃはあてのこと、ヘタレの\nホジナシって思ってっかもだけど…\n前より成長したとこ、見せっから！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (378, 5, "", "", 4, "vo_empress_135801_002", 1, "vo_empress_135801_002", "ユキノ", 0, 135801, "田舎者で世間知らずなあてだけど…\n騎士さと一緒にいろんなとこ行って\n大切な思い出、いっぱいできたよ…\nだから守りてぇんだ、この世界…！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (379, 5, "", "", 4, "vo_empress_135801_003", 2, "vo_empress_135801_003", "ユキノ", 0, 135803, "あ、あても、ちったぁでけぇけど…\n幻境竜后、で、でっかすぎ…！\nそ、それに竜まで…！　炎浴びたら\nあて、溶けちまうよぅ…！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (380, 5, "", "", 4, "vo_empress_135801_004", 3, "vo_empress_135801_004", "ユキノ", 135801, 135802, "「あてなんか」なんて、考えね…\n騎士さが信じてくれるなら、\nあてだって自分のこと、信じるよ\nあてと騎士さなら大丈夫、って…！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (381, 3, 10000, 1, 4, "vo_empress_135901_001", 4001, "vo_empress_135901_001", "サツキ", 0, 135903, "リザ公…手前ェどの面下げて\n俺の前に出てきやがった\nまァいいさ、何聞いても今更だ\nここで落とし前つけてもらうぜ", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (382, 5, "", "", 4, "vo_empress_135901_002", 1, "vo_empress_135901_002", "サツキ", 0, 135901, "いつ死んでもいいなんて\nもう思っちゃいねぇさ\nこの悪玉どもより、図太くしぶとく\n生き抜いてやろうじゃねぇか", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (383, 5, "", "", 4, "vo_empress_135901_003", 2, "vo_empress_135901_003", "サツキ", 0, 135901, "あれが幻境竜后か…\nハンパじゃねェや\nしゃあねぇ、こうなりゃ一丁\n死に花咲かすとするか", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (384, 5, "", "", 4, "vo_empress_135901_004", 3, "vo_empress_135901_004", "サツキ", 135901, 135902, "世界だの未来だの現実だの…\n重いったらありゃしねぇぜ\n潰れるなよ、騎士公\n俺も一緒に担いでやっからさ", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (385, 5, "", "", 4, "vo_empress_136001_001", 1, "vo_empress_136001_001", "アラクネ", 0, 136001, "騎士さま、どうかご安心を…\nどれだけ厳しい運命が待って\nいたとしても…あなたのことは、\nわたしの糸が必ずお守りします", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (386, 3, 10000, 1, 4, "vo_empress_136001_002", 4003, "vo_empress_136001_002", "アラクネ", 0, 136001, "…？　あの金髪の女性、なんだか\n見覚えあるような気が…いえ\n騎士さまの敵は、わたしの敵です\nそれだけです…", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (387, 5, "", "", 4, "vo_empress_136001_003", 2, "vo_empress_136001_003", "アラクネ", 0, 136003, "あれが幻境竜后さま…\nなんという恐るべき力\n…騎士さま、わたしの後ろに\n一度くらいは、庇えるはずです…", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (388, 5, "", "", 4, "vo_empress_136001_004", 3, "vo_empress_136001_004", "アラクネ", 136001, 136002, "騎士さまという光が、わたしに力を\n与えてくれるのです。ともに未来を\n歩むためにも…この戦いに\n必ず勝ちましょう、騎士さま", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (389, 5, "", "", 4, "vo_empress_136201_001", 1, "vo_empress_136201_001", "ナーナ", 0, 136201, "強そうな敵さんがいっぱい～っ！？\nこーなったら、ウルトラとっておき\nドーナツ！　ちょっと湿気てるけど\n…はい騎士ちゃん、あーんっ♪", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (390, 5, "", "", 4, "vo_empress_136201_002", 1, "vo_empress_136201_002", "ナーナ", 0, 136201, "ナーナだって頑張れるんだよっ！\n騎士ちゃんに、そう教わったもん！\nだから、すごく怖いけど…でもっ…\nナーナ、逃げたりしないよぉっ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (391, 5, "", "", 4, "vo_empress_136201_003", 2, "vo_empress_136201_003", "ナーナ", 0, 136201, "うぅ…あ、足が震えてきちゃった…\nでも動かなきゃ、戦わなきゃっ…\nわかってるのに、でもでもぉ…\nうえぇぇん、やっぱり怖いぃぃ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (392, 5, "", "", 4, "vo_empress_136201_004", 3, "vo_empress_136201_004", "ナーナ", 136201, 136202, "今のナーナはよわよわウサギじゃ\nないんだよ。騎士ちゃんのためなら\nどんな敵さんだってやっつけちゃう\nつよつよウサギなんだから！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (393, 3, 10000, 1, 4, "vo_empress_136901_001", 4001, "vo_empress_136901_001", "ルルィ", 0, 136903, "リーザ姉しゃまが裏切ったなんて\nあたち、信じたくないでしゅ…！\nだから直接聞きにいきましゅ\n吸盤ぜんぶで捕まえてでも…！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (394, 5, "", "", 4, "vo_empress_136901_002", 1, "vo_empress_136901_002", "ルルィ", 0, 136901, "姫姉しゃまも騎士しゃんも\nみなしゃん戦ってるんでしゅ\nあたちだって負けましぇん！\n一生懸命がんばりましゅ～！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (395, 5, "", "", 4, "vo_empress_136901_003", 2, "vo_empress_136901_003", "ルルィ", 0, 136903, "あ、あの方、こわいでしゅ…！\n丸呑みにされちゃいそうでしゅっ\nうじゅ…がんばりたいでしゅが…\n震えが止まらないでしゅ…！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (396, 5, "", "", 4, "vo_empress_136901_004", 3, "vo_empress_136901_004", "ルルィ", 136901, 136902, "あたちは強くないでしゅけど\n騎士しゃんとの約束がありましゅ\nだから誰にも負けましぇん！\nいっちょに、守りましゅよ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (397, 5, "", "", 4, "vo_empress_139501_001", 1, "vo_empress_139501_001", "リリ", 0, 139501, "これから挑む敵がどれだけ強いと\nしても、勇往邁進していきます\nですからこの戦いでも、兄様の\nおそばで戦わせてくださいませ", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (398, 3, 10000, 1, 4, "vo_empress_139501_002", 4002, "vo_empress_139501_002", "リリ", 0, 139503, "幻境竜后の手先、アルシャト…！\nリアさんやヴルム様を陥れた貴方を\n決して許す訳には参りません！\n不倶戴天─ここで成敗致します！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (399, 5, "", "", 4, "vo_empress_139501_003", 2, "vo_empress_139501_003", "リリ", 0, 139503, "幻境竜后の力…これほどまでに\n強力無比だとは…で、ですが…\n何があろうとわたくしは兄様を\nお守りします…命に代えても、必ず", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (400, 5, "", "", 4, "vo_empress_139501_004", 3, "vo_empress_139501_004", "リリ", 125801, 139502, "兄様への想いと、重ねてきた大切な\n時間が、たくさんの勇気と限界を\n超える奇跡をくれました。全ての人\nを救うため、参りましょう兄様…！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (401, 5, "", "", 4, "vo_empress_139601_001", 1, "vo_empress_139601_001", "クリア", 0, 139603, "お兄さん、もし怪我しちゃっても\nすぐに治癒しますからご安心を！\nわたし決めましたから…もう二度と\n自分自身から逃げないって…！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (402, 3, 10000, 1, 4, "vo_empress_139601_002", 4002, "vo_empress_139601_002", "クリア", 0, 139603, "…アルシャトさん…\n謝ったって許してあげませんよ？\nあなたの前では、わたしちょっと\nいい子じゃいられませんから…っ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (403, 5, "", "", 4, "vo_empress_139601_003", 2, "vo_empress_139601_003", "クリア", 0, 139603, "うぅっ…これが本気の幻境竜后…！\n…こんなの勝てっこありませんよ…\n…せめてお兄さんだけでも…なんて\n最後まで…諦めませんからっ…！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (404, 5, "", "", 4, "vo_empress_139601_004", 3, "vo_empress_139601_004", "クリア", 126001, 139601, "お兄さんの気持ちが胸に溢れて…\nあ、えへへ…なんだか視界が\n滲んできちゃいました…♪\nわたしはもう、負けませんよ…っ！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (405, 5, "", "", 4, "vo_empress_139701_001", 1, "vo_empress_139701_001", "プレシア", 0, 139701, "てき、いっぱい、しかも、つよすぎ\nけど、まけないよ\nお兄のほっぺ、たべて\nふるぱわー", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (406, 5, "", "", 4, "vo_empress_139701_002", 1, "vo_empress_139701_002", "プレシア", 0, 139701, "ん\nまだまだ、いける\nお兄、パパ、なかま、いる\nむしゃぶるい", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (407, 5, "", "", 4, "vo_empress_139701_003", 2, "vo_empress_139701_003", "プレシア", 0, 139703, "しょうり、みえない\nせいぎ、まもれない\nそんなの、いや\nあきらめないよ、さいごまで", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (408, 5, "", "", 4, "vo_empress_139701_004", 3, "vo_empress_139701_004", "プレシア", 126101, 139702, "て、つなぐ\nせいめいりょく、たかまる\nぜったいしょうり！", 1);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (409, 5, "", "", 4, "vo_empress_140301_004", 3, "vo_empress_140301_004", "ティア", 140301, 140301, "七冠、幻境竜后──LoAの開発者\nあんたにコワいコト教えてあげるわ\n些細なバグと思って放置したら\nゲームを壊すこともあるってね…♪", 1);
